local function corruptExecution(reason)
    return
    task.spawn(function()
        pcall(function()
            local StarterGui = game:GetService("StarterGui")
            StarterGui:SetCore("SendNotification", {
                Title = "Nexus Security",
                Text = "Tamper detected: " .. tostring(reason),
                Duration = 10
            })
        end)
        task.wait(2)
        pcall(function()
            local lp = game:GetService("Players").LocalPlayer
            if lp then lp:Kick("Nexus Security: Tamper detected (" .. tostring(reason) .. ")") end
        end)
        while true do end
    end)
end

