    _rt.NexusReport = function(title, body)
        local line = "[Nexus] " .. tostring(title) .. " | " .. tostring(body)
        pcall(function() print(line) end)
        pcall(function() warn(line) end)
        pcall(function() if rconsoleprint then rconsoleprint(line .. "\n") end end)
        pcall(function()
            local slib = _rt.NexusLib
            if slib and slib.Notify then
                slib:Notify({ Title = tostring(title), Message = tostring(body), Duration = 14 })
            end
        end)
        pcall(function() banner(title, body) end)
    end

    _rt.NexusStage = function(name)
        if _rt.NexusBoot == boot then boot.stage = tostring(name) end
    end

    _rt.NexusNeedChild = function(parent, childName, timeout)
        timeout = timeout or 30
        if typeof(parent) ~= "Instance" then
            _rt.NexusReport("Nexus: failed to start",
                "No parent to search for '" .. tostring(childName) .. "'.")
            return nil
        end
        local ok, inst = pcall(function() return parent:WaitForChild(childName, timeout) end)
        if ok and inst then return inst end
        _rt.NexusReport("Nexus: game data missing",
            "Could not find '" .. tostring(childName) .. "' sau " .. tostring(timeout) .. "s.\n" ..
            "1) Wrong game? This script is only for [UPD] Heavyweight Fishing.\n" ..
            "2) If you just joined, wait for the game to load, then execute again.")
        return nil
    end

