    local function trim(s)
        return (tostring(s):gsub("^%s+", ""):gsub("%s+$", ""))
    end
    local function readKey()
        if type(_rt.Key) == "string" then
            local k = trim(_rt.Key)
            if #k >= 4 then return k end
        end
   ]=],[=[
     local found
        for _, fname in ipairs(GUARD.KEY_FILES) do
            pcall(function()
                if not found and isfile and readfile and isfile(fname) then
                    local s = readfile(fname)
                    if type(s) == "string" and #trim(s) >= 4 then found = trim(s) end
                end
            end)
            if found then break end
        end
        return found
    end

    local function notify(msg)
        -- 1) print luon hoat dong tren moi executor
        pcall(function() print("[Nexus Hub] " .. tostring(msg)) end)
        -- 2) NexusLib neu co (khong dung notify Roblox)
        pcall(function()
            local slib = _rt.NexusLib
            if slib and slib.Notify then slib:Notify({ Title = "Nexus Hub", Message = msg, Duration = 6 }) end
        end)
    end

    local function deny(reason)
        notify(reason)
        pcall(function()
            if _rt.NexusReport then
                _rt.NexusReport("Nexus: Thong bao key", tostring(reason) ..
                    "\n\nExecute source truc tiep da bi KHOA. Phai dung loader hwfnew de vao.")
            end
