-- ===== NEXUSLIB LOADER =====
pcall(function() runtimeEnv.NexusStage("tai NexusLib") end)
local NexusLib = runtimeEnv.NexusLib
if not NexusLib then
    local LIB_URL = "https://raw.githubusercontent.com/Ngmankhoi/my-hub/main/NexusLib.lua"
    local source = nil
    pcall(function()
        if isfile and readfile and isfile("NexusLib.lua") then
            local s = readfile("NexusLib.lua")
            if type(s) == "string" and #s > 5000 and s:find("CreateWindow", 1, true) then source = s end
        end
    end)
    if not source then
        local reqFn = (syn and syn.request) or http_request or request or (http and http.request) or (fluxus and fluxus.request)
        if type(reqFn) == "function" then
            pcall(function()
                local r = reqFn({ Url = LIB_URL, Method = "GET" })
                local body = r and (r.Body or r.body)
                if type(body) == "string" and #body > 5000 then source = body end
            end)
        end
    end
    if not source then
        pcall(function() local s = game:HttpGet(LIB_URL); if type(s) == "string" and #s > 5000 then source = s end end)
    end
    if not source then
        pcall(function() local s = game:GetService("HttpService"):GetAsync(LIB_URL); if type(s) == "string" and #s > 5000 then source = s end end)
    end
    if not source then
        local msg = "[Nexus] Could not download NexusLib. This executor lacks HTTP support."
        pcall(function() print(msg) end)
        pcall(function() runtimeEnv.NexusReport("Nexus Hub", msg) end)
        return
    end
    if type(loadstring) ~= "function" then
        pcall(function() runtimeEnv.NexusReport("Nexus: executor not supported", "This executor has no loadstring -> the hub cannot run.\nUse a different executor.") end)
        return
    end
    local chunk, compileErr = loadstring(source, "@NexusLib.lua")
    if not chunk then
        local msg = "[Nexus] NexusLib compile error: " .. tostring(compileErr)
        pcall(function() print(msg) end)
        pcall(function() runtimeEnv.NexusReport("Nexus Hub", msg) end)
        return
    end
    local ok, lib = pcall(chunk)
    if not ok or type(lib) ~= "table" then
        local msg = "[Nexus] NexusLib runtime error: " .. tostring(lib)
        pcall(function() print(msg) end)
        pcall(function() runtimeEnv.NexusReport("Nexus Hub", msg) end)
        return
    end
    NexusLib = lib
    runtimeEnv.NexusLib = lib
end

