    function I18n.getCurrentLanguage()
        if NexusState.currentLanguage == "auto" then
            return NexusState.detectedLanguage or "en"
        end
        return NexusState.currentLanguage or "en"
    end

    function I18n.get(key, fallback)
        if not key or type(key) ~= "string" then return fallback or key end
        local lang = I18n.getCurrentLanguage()
        if lang == "en" then return fallback or key end
        local dict = DICTIONARY[lang]
        if dict and dict[key] then return dict[key] end
        return fallback or key
    end

    local function translateObject(obj)
        if not obj or typeof(obj) ~= "Instance" then return end
        local lang = I18n.getCurrentLanguage()
        if lang == "en" then return end
        pcall(function()
            if (obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox")) then
                local currentText = obj.Text
                if not currentText or #currentText == 0 then return end
                
                local dict = DICTIONARY[lang]
                
                local orig = obj:GetAttribute("NexusOrigText")
                if not orig or (dict and dict[currentText]) then
                    orig = currentText
                    obj:SetAttribute("NexusOrigText", orig)
                end
                
                if orig and #orig > 0 then
                    if lang == "en" then
                        if obj.Text ~= orig then
                            obj.Text = orig
                        end
                    else
                        local trans = dict and dict[orig]
                        if trans and obj.Text ~= trans then
                            obj.Text = trans
                        end
                    end
                end
            end
        end)
    end

    local function applyLanguageToGui(gui)
        if not gui then return end
        pcall(function()
            for _, desc in ipairs(gui:GetDescendants()) do
                translateObject(desc)
            end
        end)
    end

    function I18n.applyLanguage()
        local pg ]=],[=[
= LocalPlayer:FindFirstChild("PlayerGui")
        if pg then
            applyLanguageToGui(pg:FindFirstChild("NexusPanel"))
            applyLanguageToGui(pg:FindFirstChild("NexusNotifications"))
        end
        pcall(function()
            local cg = game:GetService("CoreGui")
            if cg then
                applyLanguageToGui(cg:FindFirstChild("NexusPanel"))
                applyLanguageToGui(cg:FindFirstChild("NexusNotifications"))
            end
        end)
    end

    function I18n.initListeners()
        local function hookGui(gui)
            if not gui then return end
            gui.DescendantAdded:Connect(function(desc)
                task.wait(0.03)
                translateObject(desc)
            end)
        end

        local pg = LocalPlayer:FindFirstChild("PlayerGui")
        if pg then
            local panel = pg:FindFirstChild("NexusPanel")
            if panel then hookGui(panel) end
            local notifs = pg:FindFirstChild("NexusNotifications")
            if notifs then hookGui(notifs) end

            pg.ChildAdded:Connect(function(child)
                if child.Name == "NexusPanel" or child.Name == "NexusNotifications" then
                    hookGui(child)
                    task.wait(0.1)
                    applyLanguageToGui(child)
                end
            end)
        end

        pcall(function()
            local cg = game:GetService("CoreGui")
            if cg then
                local panel = cg:FindFirstChild("NexusPanel")
                if panel then hookGui(panel) end
                local notifs = cg:FindFirstChild("NexusNotifications")
                if notifs then hookGui(notifs) end

                cg.ChildAdded:Connect(function(child)
                    if child.Name == "NexusPanel" or child.Name == "NexusNotifications" then
                        hookGui(child)
                        task.wait(0.1)
                        applyLanguageToGui(child)
                    end
                end)
            end
        end)
    end
end

-- ===== FAKE NAME (STREAMER MODE) CORE =====
-- ============================================================
do
    local realName = LocalPlayer.Name
    local realDisplayName = LocalPlayer.DisplayName
    local fakeNameConn = nil
    local fakeNameThread = nil
    local maskIdsInText -- forward declare (dinh nghia ben duoi)

    local function replacePlain(text, find, repl)
        if find == "" then return text end
        local parts = {}
        local start = 1
        while true do
            local s, e = string.find(text, find, start, true)
            if not s then
                table.insert(parts, string.sub(text, start))
                break
            end
            table.insert(parts, string.sub(text, start, s - 1))
            table.insert(parts, repl)
            start = e + 1
        end
        return table.concat(parts)
    end

    local function replaceTextInObject(obj)
        if not NexusState.fakeNameEnabled then return end
        if not obj or typeof(obj) ~= "Instance" then return end
        pcall(function()
            if typeof(obj) == "Instance" and typeof(obj) == "Instance" and obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
                local text = obj.Text
                if text and #text > 0 then
                    local updated = false
                    if realDisplayName ~= "" and string.find(text, realDisplayName, 1, true) then
                        text = replacePlain(text, realDisplayName, NexusState.fakeDisplayName or "NexusPlayer")
                        updated = true
                    end
                    if realName ~= "" and string.find(text, realName, 1, true) then
                        text = replacePlain(text, realName, NexusState.fakeName or "NexusPlayer")
                        updated = true
                    end
                    -- Guild display: doi ten guild that -> fake guild de khong bi ban
                    if NexusState.realGuildName and #NexusState.realGuildName > 0 then
                        local rg = tostring(NexusState.realGuildName)
                        if rg ~= "ZION" and not string.find(text, "ZION", 1, true) and string.find(text, rg, 1, true) then
                            text = replacePlain(text, rg, NexusState.fakeGuildName or "NexusGuild")
                            updated = true
                        end
                    end
                    -- Che luon ID (UserId / PlaceId / JobId) chu khong chi ten
                    if maskIdsInText then
                        local masked, idChanged = maskIdsInText(text)
                        if idChanged then
                            text = masked
                            updated = true
                        end
                    end
                    if updated then
                        obj.Text = text
                    end
                end
            end
        end)
    end

    -- Che ID: doi ten khong thoi van bi report vi nguoi ta doc UserId / PlaceId /
    -- JobId tren man hinh (hoac trong anh chup). Nen phai che luon cac ID nay.
    local realUserId = tostring(LocalPlayer.UserId)
    local realPlaceId = tostring(game.PlaceId)

    function maskIdsInText(text)
        if not NexusState.fakeNameEnabled then return text, false end
        local changed = false
        if #realUserId >= 5 and string.find(text, realUserId, 1, true) then
            if (NexusState.fakeIdMode or 1) == 2 then
                text = string.gsub(text, realUserId, "****")
            else
                text = string.gsub(text, realUserId, tostring(NexusState.fakeUserId or "0"))
            end
            changed = true
        end
        if #realPlaceId >= 5 and string.find(text, realPlaceId, 1, true) then
            text = string.gsub(text, realPlaceId, "0000000000")
            changed = true
        end
        local guidPat = "%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x"
        if string.find(text, guidPat) then
            text = string.gsub(text, guidPat, "********-****-****-****-************")
            changed = true
        end
        return text, changed
    end

    local function applyFakeNameToAll()
        if not NexusState.fakeNameEnabled then return end
        local pg = LocalPlayer:FindFirstChild("PlayerGui")
        if pg then
            for _, v in ipairs(pg:GetDescendants()) do
                replaceTextInObject(v)
            end
        end
        local char = LocalPlayer.Character
        if char then
            for _, v in ipairs(char:GetDescendants()) do
                replaceTextInObject(v)
            end
        end
        pcall(function()
            local cg = game:GetService("CoreGui")
            if cg then
                for _, v in ipairs(cg:GetDescendants()) do
                    replaceTextInObject(v)
                end
            end
        end)
    end

    function NexusState.enableFakeName()
        if NexusState.fakeNameEnabled then return end
        NexusState.fakeNameEnabled = true
        applyFakeNameToAll()

        local pg = LocalPlayer:FindFirstChild("PlayerGui")
        if pg then
            fakeNameConn = pg.DescendantAdded:Connect(function(desc)
                if NexusState.fakeNameEnabled then
                    task.wait(0.05)
                    replaceTextInObject(desc)
                end
            end)
        end

        fakeNameThread = task.spawn(function()
            while NexusState.fakeNameEnabled do
                pcall(applyFakeNameToAll)
                task.wait(1.5)
            end
        end)
        NexusLib:Notify({ Title = "Streamer Mode", Message = "Fake name active: " .. tostring(NexusState.fakeName), Duration = 2 })
    end

    function NexusState.disableFakeName()
        NexusState.fakeNameEnabled = false
        if fakeNameConn then fakeNameConn:Disconnect(); fakeNameConn = nil end
        if fakeNameThread then task.cancel(fakeNameThread); fakeNameThread = nil end
        NexusLib:Notify({ Title = "Streamer Mode", Message = "Fake name disabled", Duration = 2 })
    end
end

-- ============================================================
-- Chong "cau tren troi": khi dang bay / vua teleport, player lo lung tren khong
-- nen phao khong roi trung nuoc -> cast phi hoai. Raycast xuong kiem tra nuoc.
function NexusState.isOverWater()
    local ok, result = pcall(function()
        local char = LocalPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if not root then return false end

        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = { char }
        params.IgnoreWater = false

        local hit = Workspace:Raycast(root.Position, Vector3.new(0, -200, 0), params)
        if not hit then return false end

        if hit.Instance == Workspace.Terrain and hit.Material == Enum.Material.Water then
            return true
        end
        local n = string.lower(hit.Instance.Name)
        if string.find(n, "water") or string.find(n, "ocean") or string.find(n, "sea") then
            return true
        end
        return false
    end)
    if not ok then return true end -- loi thi cho cast, khong chan oan
    return result
end

function NexusState.canCastNow()
    if NexusState.flying then return false end
    -- Khi bat auto cast / farm boss / farm secret: tele len troi la chu y
    -- (chong detect), vay isOverWater se false -> bo qua kiem tra nuoc,
    -- chi chan khi dang fly thu cong.
    local F = NexusState.Fishing and NexusState.Fishing.Flags
    if F and (F.AutoCast or F.AutoFarmBoss or F.AutoFarmSecretBoss) then
        return true
    end
    return NexusState.isOverWater()
end

-- ===== UNIVERSAL BAIT MERCHANT LOCATOR =====
-- ============================================================
local function findBaitMerchantHRP()
    local char = LocalPlayer.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    local myPos = root and root.Position or Vector3.new(0, 0, 0)
    local bestHRP = nil
    local bestDist = math.huge

    pcall(function()
        local npcFolder = Workspace:FindFirstChild("NPC")
        if npcFolder then
            local bb = npcFolder:FindFirstChild("BuyBait")
            if bb then
                for _, model in ipairs(bb:GetChildren()) do
                    if typeof(model) == "Instance" and typeof(model) == "Instance" and model:IsA("Model") then
                        local hrp = model:FindFirstChild("HumanoidRootPart") or model:FindFirstChild("Torso") or model.PrimaryPart
                        if hrp then
                            local dist = (hrp.Position - myPos).Magnitude
                            if dist < bestDist then
                                bestDist = dist
                                bestHRP = hrp
                            end
                        end
                    end
                end
            end
            local func = npcFolder:FindFirstChild("Function")
            if func then
                for _, model in ipairs(func:GetChildren()) do
                    if typeof(model) == "Instance" and typeof(model) == "Instance" and model:IsA("Model") and (string.find(model.Name:lower(), "bait") or string.find(model.Name:lower(), "shop") or string.find(model.Name:lower(), "merchant")) then
                        local hrp = model:FindFirstChild("HumanoidRootPart") or model:FindFirstChild("Torso") or model.PrimaryPart
                        if hrp then
                            local dist = (hrp.Position - myPos).Magnitude
     ]=],[=[
                       if dist < bestDist then
                                bestDist = dist
                                bestHRP = hrp
                            end
                        end
                    end
                end
            end
            if not bestHRP then
                for _, desc in ipairs(npcFolder:GetDescendants()) do
                    if typeof(desc) == "Instance" and typeof(desc) == "Instance" and desc:IsA("Model") and string.find(desc.Name:lower(), "bait") then
                        local hrp = desc:FindFirstChild("HumanoidRootPart") or desc:FindFirstChild("Torso") or desc.PrimaryPart
                        if hrp then
                            local dist = (hrp.Position - myPos).Magnitude
                            if dist < bestDist then
                                bestDist = dist
                                bestHRP = hrp
                            end
                        end
                    end
                end
            end
        end
    end)
    return bestHRP
end

