-- Parse one Data inventory child into (fishName, weightKg, count).
-- Real server format: Name = "FishName | 3500000 KG" (may add " | Favorite"),
-- Value = stack count (IntValue). Older format kept as fallback.
local function parseCraftWeight(str)
    if not str or str == "" then return nil end
    local s = tostring(str):gsub("^%s+", ""):gsub("%s+$", "")
    s = s:gsub("%s*[Kk][Gg]%s*$", "")
    s = s:gsub("^%s+", ""):gsub("%s+$", "")
    local direct = tonumber(s)
    if direct then return direct end
    local num, suffix = s:match("^([%d%.]+)%s*([KkMmBbTt])%+?$")
    num = tonumber(num)
    if not num then return nil end
    local mult = { K = 1000, M = 1000000, B = 1000000000, T = 1000000000000 }
    local m = mult[string.upper(suffix or "")]
    if not m then return nil end
    return num * m
end

local function parseCraftFishEntry(item)
    if not item then return nil, nil, 0 end
    local rawName = tostring(item.Name or "")
    rawName = string.split(rawName, "| Favorite")[1]
    local count = 1
    pcall(function()
        if type(item.Value) == "number" then count = item.Value end
    end)
    local parts = {}
    for part in string.gmatch(rawName, "[^|]+") do table.insert(parts, part) end
    local function trim(s) return tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", "") end
    local fishName = trim(parts[1])
    local weight = nil
    if #parts >= 2 then
        weight = parseCraftWeight(string.split(trim(parts[2]), " ")[1])
    end
    if not weight then
        pcall(function()
            local w = item:GetAttribute("Weight")
            if type(w) == "number" and w > 0 then weight = w end
        end)
    end
    if (not weight) and type(item.Value) == "string" and string.find(item.Value, "|", 1, true) then
        local vparts = {}
        for part in string.gmatch(item.Value, "[^|]+") do table.insert(vparts, part) end
        if #vparts >= 2 then
            weight = parseCraftWeight(string.split(trim(vparts[2]), " ")[1])
        end
        if fishName == "" and #vparts >= 1 then fishName = trim(vparts[1]) end
    end
    if fishName == "" then return nil, nil, 0 end
    if type(count) ~= "number" or count < 1 then count = 1 end
    return fishName, weight, math.floor(count)
end

local function GetBuyableBaits()
    local _bbNow = tick()
    if NexusState.cachedBuyableBaits and NexusState.cachedBuyableBaitsAt and (_bbNow - NexusState.cachedBuyableBaitsAt < 30) then
        return NexusState.cachedBuyableBaits
    end
    local baits = {}
    if not Info or not Info:FindFirstChild("Bait") then return {"No bait available"} end
    for _, child in pairs(Info.Bait:GetChildren()) do
        if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("ModuleScript") then
            local success, mod = pcall(require, child)
            if success and type(mod) == "table" and mod.Price and mod.Price > 0 then
                table.insert(baits, child.Name)
            end
        end
    end
    if #baits == 0 then return {"No bait available"} end
    NexusState.cachedBuyableBaits = baits
    NexusState.cachedBuyableBaitsAt = _bbNow
    return baits
end

