end

-- ============================================================

-- ============================================================
-- ===== CONFIG SYSTEM (save / load / auto-load / import-export) =====
-- ============================================================
-- Every Toggle / Dropdown / MultiDropdown / Textbox with a static English Name is
-- registered here through Cfg.wrap(kind, name, config) at creation time. The config
-- table itself is untouched (defaults still come from Default = ...), the registry
-- only keeps the live handle so save/load can Get/Set values later.
--
-- Save format is a flat { [controlName] = value } table, JSON-encoded. Control
-- names are unique across the whole hub (verified), so no tab/section prefix is
-- needed and configs stay compatible even if a control moves sections.
do
    local ConfigSys = {}
    ConfigSys.registry = {}   -- [name] = { kind = "toggle"|"dropdown"|"multi"|"text", get = fn, set = fn }
    ConfigSys.ordered = {}    -- registration order, for stable exports
    ConfigSys.FILE = "NexusHub_Config.json"
    ConfigSys.AUTO_FILE = "NexusHub_AutoLoad.json"
    ConfigSys._saving = false

    local function cfgKind(callKind)
        if callKind == "Toggle" then return "toggle" end
        if callKind == "Dropdown" then return "dropdown" end
        if callKind == "MultiDropdown" then return "multi" end
        return "text"
    end

    -- Wrap a control config table: pass through untouched, remember the name so
    -- the returned handle can be registered right after creation.
    function ConfigSys.wrap(callKind, name, config)
        config = config or {}
        config._CfgKind = callKind
        config._CfgName = name
        return config
    end

    function ConfigSys.register(handle, callKind, name, config)
        if not handle or not name then return handle end
        local kind = cfgKind(callKind)
        local entry = ConfigSys.registry[name]
        if not entry then
            entry = { kind = kind }
            ConfigSys.registry[name] = entry
            table.insert(ConfigSys.ordered, name)
        end
        entry.kind = kind
        -- The original Callback is captured here at registration time (from the
        -- config table), because NexusLib handles do not expose it.
        local cb = config and config.Callback or nil
        if type(handle.Get) == "function" then
            entry.get = function()
                local ok, v = pcall(handle.Get)
                return ok and v or nil
            end
        end
        -- NOTE: NexusLib Set() implementations do NOT fire Callback (toggle Set
        -- calls set(v, false); dropdown/text Set only touch the label). After
        -- Set we therefore re-fire the captured Callback so the hub state
        -- (Fishing.Flags, NexusState, ...) actually follows the loaded value.
        if type(handle.Set) == "function" then
            entry.set = function(v)
                pcall(handle.Set, handle, v)
                if cb then
                    task.spawn(cb, v)
                end
            end
        elseif cb then
            entry.set = function(v)
                task.spawn(cb, v)
            end
        end
        return handle
    end

    function ConfigSys.snapshot()
        local out = {}
        for name, entry in pairs(ConfigSys.registry) do
            if entry.get then
                local ok, v = pcall(entry.get)
                if ok and v ~= nil then out[name] = v end
            end
        end
        return out
    end

    function ConfigSys.apply(data)
        if type(data) ~= "table" then return 0, 0 end
        local okCount, missCount = 0, 0
        for name, value in pairs(data) do
            local entry = ConfigSys.registry[name]
            if entry and entry.set then
                local ok = pcall(entry.set, value)
                if ok then okCount = okCount + 1 else missCount = missCount + 1 end
            else
                missCount = missCount + 1
            end
        end
        return okCount, missCount
    end

    local function encode(data)
        local HttpService = Services.HttpService
        local ok, s = pcall(HttpService.JSONEncode, HttpService, data)
        return ok and s or nil
    end

    local function decode(s)
        local HttpService = Services.HttpService
        local ok, data = pcall(HttpService.JSONDecode, HttpService, s)
        if ok and type(data) == "table" then return data end
        return nil
    end

    function ConfigSys.save(slot)
        local payload = encode({ version = 1, savedAt = os.time(), data = ConfigSys.snapshot() })
        if not payload then
            NexusLib:Notify({ Title = "Config", Message = "Encode failed.", Duration = 3 })
            return false
        end
        if not writefile then
            NexusLib:Notify({ Title = "Config", Message = "This executor cannot save files.", Duration = 3 })
            return false
        end
        local ok = pcall(writefile, slot or ConfigSys.FILE, payload)
        NexusLib:Notify({ Title = "Config", Message = ok and "Saved." or "Save failed.", Duration = 2 })
        return ok
    end

    function ConfigSys.load(slot, silent)
        if not (isfile and readfile) then
            if not silent then NexusLib:Notify({ Title = "Config", Message = "This executor cannot read files.", Duration = 3 }) end
            return false
        end
        local path = slot or ConfigSys.FILE
        local has = false
        pcall(function() has = isfile(path) end)
        if not has then
            if not silent then NexusLib:Notify({ Title = "Config", Message = "No saved config found.", Duration = 3 }) end
            return false
        end
        local ok, raw = pcall(readfile, path)
        if not ok or not raw then
            if not silent then NexusLib:Notify({ Title = "Config", Message = "Read failed.", Duration = 3 }) end
            return false
        end
        local wrap = decode(raw)
        local data = wrap and (wrap.data or wrap) or nil
        if not data then
            if not silent then NexusLib:Notify({ Title = "Config", Message = "Config file is corrupt.", Duration = 3 }) end
            return false
        end
        -- Defer one frame so every tab has finished building its controls.
        task.defer(function()
            local okCount, missCount = ConfigSys.apply(data)
            if not silent then
                NexusLib:Notify({ Title = "Config", Message = "Loaded " .. okCount .. " settings" .. (missCount > 0 and " (" .. missCount .. " skipped)" or "") .. ".", Duration = 3 })
            end
        end)
        return true
    end

    function ConfigSys.exportCode()
        local payload = encode({ version = 1, savedAt = os.time(), data = ConfigSys.snapshot() })
        if not payload then return nil end
        local clip = (syn and syn.write_clipboard) or setclipboard or toclipboard
        if clip then
            pcall(clip, payload)
            NexusLib:Notify({ Title = "Config", Message = "Config code copied to clipboard.", Duration = 3 })
        else
            NexusLib:Notify({ Title = "Config", Message = "Clipboard not supported on this executor.", Duration = 3 })
        end
        return payload
    end

    -- Import reads the clipboard when the executor exposes it; otherwise it falls
    -- back to the textbox value typed/pasted by the user.
    function ConfigSys.importCode(text)
        local code = text
        if (not code or code == "") and getclipboard then
            pcall(function() code = getclipboard() end)
        end
        if not code or code == "" then
            NexusLib:Notify({ Title = "Config", Message = "Paste a config code first.", Duration = 3 })
            return false
        end
        local wrap = decode(code)
        local data = wrap and (wrap.data or wrap) or nil
        if not data then
            NexusLib:Notify({ Title = "Config", Message = "Invalid config code.", Duration = 3 })
            return false
        end
        task.defer(function()
            local okCount, missCount = ConfigSys.apply(data)
            NexusLib:Notify({ Title = "Config", Message = "Imported " .. okCount .. " settings" .. (missCount > 0 and " (" .. missCount .. " skipped)" or "") .. ".", Duration = 3 })
        end)
        return true
    end

    runtimeEnv.NexusConfig = ConfigSys
    runtimeEnv.NexusCfgWrap = ConfigSys.wrap
    ConfigSys._saving = false
end


