        local scriptStartTime = time()
        task.spawn(function()
        -- Cache for every stat ro]=],[=[
w
        local cachedStat1, cachedStat2, cachedStat3
        local cachedStat2_1, cachedStat2_2, cachedStat2_3
        local cachedStat3_1, cachedStat3_2, cachedStat3_3
        local cachedStat4_1
        local cachedStat4_2, cachedStat4_3
        local labelCache = {}

        local function setStat(statFrame, text)
            if not statFrame then return end
            local lbl = labelCache[statFrame]
            if not lbl or not lbl.Parent then
                for _, child in ipairs(statFrame:GetDescendants()) do
                    if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("TextLabel") and child.TextSize >= 18 then
                        lbl = child
                        labelCache[statFrame] = child
                        break
                    end
                end
            end
            if lbl and lbl.Text ~= text then lbl.Text = text end
        end

        -- Stats fetch helper
        local function getHomeStats()
            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))
            if not userData then return {} end
            local stats = {}
            local levelFolder = userData:FindFirstChild("Level")
            stats.Level = levelFolder and levelFolder:FindFirstChild("Level") and tostring(levelFolder.Level.Value) or "N/A"
            stats.Cash = userData:FindFirstChild("Cash") and tostring(userData.Cash.Value) or "N/A"
            stats.Rod = userData:FindFirstChild("FishingRod") and tostring(userData.FishingRod.Value) or "N/A"
