            stats.FishCaught = userData:FindFirstChild("FishCaught") and tostring(userData.FishCaught.Value) or "N/A"
            stats.Ticket = userData:FindFirstChild("Ticket") and tostring(userData.Ticket.Value) or "N/A"
            stats.TraitReroll = userData:FindFirstChild("Trait Reroll") and tostring(userData["Trait Reroll"].Value) or "N/A"
            stats.HeaviestWeight = userData:FindFirstChild("HeaviestWeight") and tostring(userData.HeaviestWeight.Value) or "N/A"
            stats.BaseHP = userData:FindFirstChild("BaseHP") and tostring(userData.BaseHP.Value) or "N/A"
            return stats
        end

        while task.wait(1) do
            if not alive() then break end
            pcall(function()
                local mg = MainGui
                local leaderstats = LocalPlayer:FindFirstChild("leaderstats")
                local function readNumber(names)
                    for _, name in ipairs(names) do
                        local value = (leaderstats and leaderstats:FindFirstChild(name)) or LocalPlayer:GetAttribute(name)
                        if value then
                            local raw = (typeof(value) == "Instance" and value:IsA("ValueBase")) and value.Value or value
                            if type(raw) == "number" then return tostring(raw) end
                        end
                    end
                    return nil
                end

                -- Level and Cash from leaderstats or the UI
                local lvlText = readNumber({"Level", "level", "LVL"}) or "N/A"
                if mg then
                    local lvlNode = mg:FindFirstChild("Level")
                    if lvlNode then
                        local val = lvlNode:FindFirstChild("Value")
                        if val and typeof(val) == "Instance" and val:IsA("TextLabel") then
                            local match = val.Text:match("Level:%s*(%d+)")
                            if match then lvlText = match else lvlText = val.Text end
                        end
                    end
                end
                local cashText = readNumber({"Money", "Cash", "Coins", "Gold", "money", "cash"}) or "N/A"
                if mg then
                    local cashNode = mg:FindFirstChild("Main") and mg.Main:FindFirstChild("Stats") and mg.Main.Stats:FindFirstChild("Cash")
                    if cashNode then
