                -- Session time
                local uptime = math.floor(time() - scriptStartTime)
                local h = math.floor(uptime / 3600)
                local m = math.floor((uptime % 3600) / 60)
                local s = uptime % 60
                local timeText = string.format("%02d:%02d:%02d", h, m, s)

                -- Update statRow1 (Level, Cash, Session)
                if statRow and statRow._frame then
                    if not cachedStat1 then
                        cachedStat1 = statRow._frame:FindFirstChild("Stat_1")
                        cachedStat2 = statRow._frame:FindFirstChild("Stat_2")
                        cachedStat3 = statRow._frame:FindFirstChild("Stat_3")
                    end
                    setStat(cachedStat1, lvlText)
                    setStat(cachedStat2, cashText)
                    setStat(cachedStat3, timeText)
                end

                -- Update statRow2 (Rod, Crystal, Essence)
                if statRow2 and statRow2._frame then
                    if not cachedStat2_1 then
                        cachedStat2_1 = statRow2._frame:FindFirstChild("Stat_1")
                        cachedStat2_2 = statRow2._frame:FindFirstChild("Stat_2")
                        cachedStat2_3 = statRow2._frame:FindFirstChild("Stat_3")
                    end
                    setStat(cachedStat2_1, homeStats.Rod)
                    setStat(cachedStat2_2, homeStats.Crystal)
                    setStat(cachedStat2_3, homeStats.EssenceOrb)
                end

                -- Update statRow3 (Bait, FishCaught, Ticket)
                if statRow3 and statRow3._frame then
                    if not cachedStat3_1 then
                        cachedStat3_1 = statRow3._frame:FindFirstChild("Stat_1")
                        cachedStat3_2 = statRow3._frame:FindFirstChild("Stat_2")
                        cachedStat3_3 = statRow3._frame:FindFirstChild("Stat_3")
                    end
                    setStat(cachedStat3_1, homeStats.Bait)
                    setStat(cachedStat3_2, homeStats.FishCaught)
                    setStat(cachedStat3_3, homeStats.Ticket)
                end

                -- Update statRow4 (TraitReroll)
                if statRow4 and statRow4._frame then
                    if not cachedStat4_1 then
                        cachedStat4_1 = statRow4._frame:FindFirstChild("Stat_1")
                    end
                    setStat(cachedStat4_1, homeStats.TraitReroll)
                end

                -- Update statRow5 (Heaviest Fish, BaseHP)
                if statRow4 and statRow4._frame then
                    if not cachedStat4_2 and not cachedStat4_3 then
                        cachedStat4_2 = statRow4._frame:FindFirstChild("Stat_2")
                        cachedStat4_3 = statRow4._frame:FindFirstChild("Stat_3")
                    end
                    setStat(cachedStat4_2, homeStats.HeaviestWeight)
                    setStat(cachedStat4_3, homeStats.BaseHP)
                end
            end)
        end
    end)
end

