    -- ===== AUTO NAMELESS OCTOPARASITE =====
    do
        local NAMELESS_NAME = "Nameless Octoparasite"
        local RHY_LANES = { "A", "S", "D" }
        local RHY_KEYS = { A = Enum.KeyCode.A, S = Enum.KeyCode.S, D = Enum.KeyCode.D }
        local RHY_WINDOW = 0.22
        local RHY_SPEED = 1.15 / 1.4
        local RHY_BAR_FALLBACK = 0.85

        NexusState.Nameless = {
            Enabled = false,
            Mode = "Safe",
            RiskRate = 25,
            Band = 0.08,
            Lag = 0.03,
            Active = false,
            SignalUntil = 0,
            Config = nil,
            Method = nil,
            RiskThread = nil,
            NextPress = {},
            Stats = { hit = 0, spam = 0 },
        }
        local Rhy = NexusState.Nameless

        local function rhyFindNameless()
            local roots = {}
            local ocean = Workspace:FindFirstChild("Ocean")
            if ocean then
                local boss = ocean:FindFirstChild("Boss")
                if boss then
                    local fn = boss:FindFirstChild("FishName")
                    if fn then table.insert(roots, fn) end
                    table.insert(roots, boss)
                end
                table.insert(roots, ocean)
            end
            local fishes = Workspace:FindFirstChild("Fishes")
            if fishes then table.insert(roots, fishes) end
            for _, root in ipairs(roots) do
                local ok, found = pcall(function() return root:FindFirstChild(NAMELESS_NAME, true) end)
                if ok and found then return found end
            end
            return nil
        end

        local function rhyPivotOf(inst)
            if not inst then return nil end
            local ok, cf = pcall(function()
                if typeof(inst) == "Instance" and typeof(inst) == "Instance" and inst:IsA("BasePart") then return inst.CFrame end
                if typeof(inst) == "Instance" and typeof(inst) == "Instance" and inst:IsA("Model") then
                    if inst.PrimaryPart then return inst.PrimaryPart.CFrame end
                    return inst:GetPivot()
                end
                local part = inst:FindFirstChildWhichIsA("BasePart", true)
                if part then return part.CFrame end
                return nil
            end)
            if ok and cf then return cf end
            return nil
        end

        local function rhyTeleportToNameless()
            local model = rhyFindNameless()
            if not model then
                NexusLib:Notify({ Title = "Nameless", Message = "Cannot find " .. NAMELESS_NAME .. " in Workspace (boss not spawned yet?)", Duration = 3 })
                return false
            end
            local cf = rhyPivotOf(model)
            if not cf then
                NexusLib:Notify({ Title = "Nameless", Message = "Found boss but could not get its position!", Duration = 3 })
                return false
            end
            local char = LocalPlayer.Character
            local hrp = char and (char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart)
            if not hrp then
                NexusLib:Notify({ Title = "Nameless", Message = "Character not found!", Duration = 2 })
                return false
            end
            hrp.CFrame = cf + Vector3.new(0, 12, 0)
            NexusLib:Notify({ Title = "Nameless", Message = "Teleported to " .. NAMELESS_NAME, Duration = 2 })
            return true
        end

        local function rhyPress(laneFrame, lane)
            local methods = {
                function()
                    if not firesignal then return false end
                    local btn = laneFrame and laneFrame:FindFirstChild("Button")
                    if not btn then return false end
                    if not (typeof(btn) == "Instance" and (btn:IsA("TextButton") or btn:IsA("ImageButton"))) then return false end
                    firesignal(btn.MouseButton1Click)
                    return true
                end,
                function()
                    local vim = game:GetService("VirtualInputManager")
                    vim:SendKeyEvent(true, RHY_KEYS[lane], false, game)
                    vim:SendKeyEvent(false, RHY_KEYS[lane], false, game)
                    return true
                end,
                function()
                    local vim = game:GetService("VirtualInputManager")
                    vim:SendKeyEvent(true, RHY_KEYS[lane], false, nil)
                    vim:SendKeyEvent(false, RHY_KEYS[lane], false, nil)
                    return true
                end,
            }
            if Rhy.Method then
                local ok, res = pcall(methods[Rhy.Method])
                if ok and res then return true end
                Rhy.Method = nil
            end
            for i, fn in ipairs(methods) do
                local ok, res = pcall(fn)
                if ok and res then
                    Rhy.Method = i
                    return true
                end
            end
            return false
        end

        local function rhyGui()
            local fishing = MainGui and MainGui:FindFirstChild("Fishing")
            if not fishing then return nil, nil end
            return fishing:FindFirstChild("Rhythm"), fishing
        end

        local function rhyUiActive()
            local gui, fishing = rhyGui()
            if not gui or not fishing then return false end
            return gui.Visible == true and fishing.Visible == true
        end

        local function rhyMaxBand()
            local m = RHY_WINDOW - RHY_SPEED * (Rhy.Lag or 0) - 0.02
            if m < 0.01 then m = 0.01 end
            return m
        end

        local function rhyScan(now)
            local gui = rhyGui()
            if not gui then return end
            for _, lane in ipairs(RHY_LANES) do
                local laneFrame = gui:FindFirstChild("Progression" .. lane)
                if laneFrame then
                    local barY = RHY_BAR_FALLBACK
                    local barFrame = laneFrame:FindFirstChild("BarFrame")
                    if barFrame then
                        local okB, y = pcall(function() return barFrame.Position.Y.Scale end)
                        if okB and type(y) == "number" then barY = y end
                    end
                    local band = math.clamp(Rhy.Band, 0.01, rhyMaxBand())
                    local inWindow = 0
                    for _, note in ipairs(laneFrame:GetChildren()) do
                        if note.Name == "Note_FX" then
                            local okP, y = pcall(function() return note.Position.Y.Scale end)
                            if okP and type(y) == "number" then
                                if math.abs((y + RHY_SPEED * Rhy.Lag) - barY) <= band then
                                    inWindow = inWindow + 1
                                end
                            end
                        end
                    end
                    if inWindow > 5 then inWindow = 5 end
                    for _ = 1, inWindow do
                        if rhyPress(laneFrame, lane) then
                            Rhy.Stats.hit = Rhy.Stats.hit + 1
                        end
                    end
                end
            end
        end

        local function rhyStartRisk()
            if Rhy.RiskThread then return end
            Rhy.RiskThread = task.spawn(function()
                while alive() and Rhy.Enabled and Rhy.Mode == "Risk" and Rhy.Active do
                    local rate = math.clamp(tonumber(Rhy.RiskRate) or 25, 1, 200)
                    local burst = math.max(1, math.floor(rate / 20))
                    for _ = 1, burst do
                        pcall(function() Events.RhythmHit:FireServer("hit") end)
                        Rhy.Stats.spam = Rhy.Stats.spam + 1
                    end
                    task.wait(burst / rate)
                end
                Rhy.RiskThread = nil
            end)
        end

        if runtimeEnv.NexusRhyStart then pcall(function() runtimeEnv.NexusRhyStart:Disconnect() end) end
        if runtimeEnv.NexusRhyStop then pcall(function() runtimeEnv.NexusRhyStop:Disconnect() end) end
        if runtimeEnv.NexusRhyLoop then pcall(function() runtimeEnv.NexusRhyLoop:Disconnect() end) end
        if runtimeEnv]=],[=[
.NexusNamelessBGM then pcall(function() runtimeEnv.NexusNamelessBGM:Disconnect() end) end
        if runtimeEnv.NexusNamelessP2 then pcall(function() runtimeEnv.NexusNamelessP2:Disconnect() end) end

        pcall(function()
            local evStart = Events:FindFirstChild("RhythmStart")
            if evStart then
                runtimeEnv.NexusRhyStart = evStart.OnClientEvent:Connect(function(cfg)
                    if not alive() then return end
                    Rhy.Config = cfg
                    Rhy.Active = true
                    Rhy.SignalUntil = tick() + 8
                    Rhy.Stats = { hit = 0, spam = 0 }
                    Rhy.NextPress = {}
                    if Rhy.Enabled then
                        local hp = cfg and (cfg.FinalMaxHP or cfg.HPFinalPhase)
                        NexusLib:Notify({
                            Title = "Auto Nameless",
                            Message = "Nameless started [" .. tostring(Rhy.Mode) .. "]" .. (hp and (" | HP " .. tostring(hp)) or ""),
                            Duration = 3,
                        })
                        if Rhy.Mode == "Risk" then rhyStartRisk() end
                    end
                end)
            end
            local evStop = Events:FindFirstChild("RhythmStop")
            if evStop then
                runtimeEnv.NexusRhyStop = evStop.OnClientEvent:Connect(function()
                    Rhy.Active = false
                    Rhy.SignalUntil = 0
                end)
            end
        end)

        -- Nameless remotes captured after kill (remote.txt): BossPhaseBGM(name, sound) + BossPhase2Setup().
        -- Arm the minigame on either remote so Auto Nameless works even when RhythmStart is late/missing.
        pcall(function()
            local evBGM = Events:FindFirstChild("BossPhaseBGM")
            if evBGM then
                runtimeEnv.NexusNamelessBGM = evBGM.OnClientEvent:Connect(function(bossName, _sound)
                    if not alive() then return end
                    if bossName ~= nil and tostring(bossName) ~= "Nameless Octoparasite" then return end
                    Rhy.Active = true
                    Rhy.SignalUntil = tick() + 8
                    if Rhy.Enabled then
                        NexusLib:Notify({ Title = "Auto Nameless", Message = "Nameless boss signal [" .. tostring(Rhy.Mode) .. "]", Duration = 3 })
                    end
                end)
            end
            local evP2 = Events:FindFirstChild("BossPhase2Setup")
            if evP2 then
                runtimeEnv.NexusNamelessP2 = evP2.OnClientEvent:Connect(function()
                    if not alive() then return end
                    Rhy.Active = true
                    Rhy.SignalUntil = tick() + 8
                    if Rhy.Enabled then
                        NexusLib:Notify({ Title = "Auto Nameless", Message = "Nameless phase 2 [" .. tostring(Rhy.Mode) .. "]", Duration = 3 })
                    end
                end)
            end
        end)


        runtimeEnv.NexusRhyLoop = RunService.Heartbeat:Connect(function()
            if not alive() or not Rhy.Enabled then return end
            local now = tick()
            Rhy.Active = rhyUiActive() or now < (Rhy.SignalUntil or 0)
            if not Rhy.Active then return end
            if Rhy.Mode == "Risk" then rhyStartRisk() end
            rhyScan(now)
        end)

        local NamelessSection = FarmingTab:CreateSection("Auto Nameless Octoparasite")
        NamelessSection:CreateButton({
            Name = "Teleport to Nameless Octoparasite",
            Callback = function() pcall(rhyTeleportToNameless) end
        })
        Cfg.register(NamelessSection:CreateToggle(Cfg.wrap("Toggle", "Auto Nameless", {
            Name = "Auto Nameless",
            Default = false,
            Callback = function(value)
                Rhy.Enabled = value
                if value then
                    NexusLib:Notify({ Title = "Auto Nameless", Message = "Enabled [" .. tostring(Rhy.Mode) .. "]. Waiting for Nameless signal from server.", Duration = 3 })
                    if Rhy.Active and Rhy.Mode == "Risk" then rhyStartRisk() end
                else
                    Rhy.Active = false
                    Rhy.SignalUntil = 0
                    NexusLib:Notify({ Title = "Auto Nameless", Message = "Disabled | hit " .. tostring(Rhy.Stats.hit) .. " | remote " .. tostring(Rhy.Stats.spam), Duration = 3 })
                end
            end
        })), "Toggle", "Auto Nameless", {
            Name = "Auto Nameless",
            Default = false,
            Callback = function(value)
                Rhy.Enabled = value
                if value then
                    NexusLib:Notify({ Title = "Auto Nameless", Message = "Enabled [" .. tostring(Rhy.Mode) .. "]. Waiting for Nameless signal from server.", Duration = 3 })
                    if Rhy.Active and Rhy.Mode == "Risk" then rhyStartRisk() end
                else
                    Rhy.Active = false
                    Rhy.SignalUntil = 0
                    NexusLib:Notify({ Title = "Auto Nameless", Message = "Disabled | hit " .. tostring(Rhy.Stats.hit) .. " | remote " .. tostring(Rhy.Stats.spam), Duration = 3 })
                end
            end
        })
    end

    -- ===== FAVORITES =====
    do
        local FavSection = FarmingTab:CreateSection("Auto Favorite Fish")
        local allFishNames = {}
        pcall(function()
            local rarityModule = require(Info.FishingAreaRarity)
