            if not userData then return {} end
            local skillFolder = userData:FindFirstChild("Skill")
            if not skillFolder then return {} end
            local ownedSkills = {}
            for _, child in pairs(skillFolder:GetChildren()) do
                if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("Folder") then
                    local owned = child:FindFirstChild("Owned")
                    if typeof(owned) == "Instance" and owned:IsA("BoolValue") and owned.Value == true then
