sage = "No skill selected!", Duration = 2 })
                    return
                end
                local userId = LocalPlayer and LocalPlayer.UserId
                if not userId then
                    NexusLib:Notify({ Title = "Upgrade Skill", Message = "Player not ready!", Duration = 2 })
                    return
                end
                local userData = Data and Data:FindFirstChild(tostring(userId))
                if not userData then
                    NexusLib:Notify({ Title = "Upgrade Skill", Message = "User data not found!", Duration = 2 })
                    return
                end
                local essenceOrb = userData:FindFirstChild("EssenceOrb")
                if not essenceOrb or not (typeof(essenceOrb) == "Instance" and essenceOrb:IsA("NumberValue")) then
                    NexusLib:Notify({ Title = "Upgrade Skill", Message = "EssenceOrb not found!", Duration = 2 })
                    return
                end
                if essenceOrb.Value <= 0 then
                    NexusLib:Notify({ Title = "Upgrade Skill", Message = "Not enough EssenceOrb!", Duration = 2 })
                    return
                end
                if not Events or not Events.UpgradeSkill then
                    NexusLib:Notify({ Title = "Upgrade Skill", Message = "UpgradeSkill remote not found!", Duration = 2 })
                    return
                end

                NexusState.upgradeSkill.teleported = false
                NexusState.upgradeSkill.oldPosition = nil
                if NexusState.upgradeSkill.method == "Teleport" then
                    local npc = Workspace:FindFirstChild("NPC")
                    if npc then
                        local func = npc:FindFirstChild("Function")
                        if func then
                            local zengTianguo = func:FindFirstChild("Zeng Tianguo")
                            if typeof(zengTianguo) == "Instance" and zengTianguo:IsA("Model") then
                                local hrp = zengTianguo:FindFirstChild("HumanoidRootPart")
                                if hrp then
                                    local char = LocalPlayer.Character
                                    if char then
                                        local root = char:FindFirstChild("HumanoidRootPart")
                                        if root then
                                            NexusState.upgradeSkill.oldPosition = root.Position
                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))
                                            NexusState.upgradeSkill.teleported = true
                                            task.wait(0.3)
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if not NexusState.upgradeSkill.teleported then
                        NexusLib:Notify({ Title = "Upgrade Skill", Message = "Could not find Zeng Tianguo, teleport failed. Continuing anyway.", Duration = 3 })
                    end
                end

                local success, err = pcall(function()
                    return Events.UpgradeSkill:InvokeServer(selectedSkill)
                end)

                if NexusState.upgradeSkill.teleported and NexusState.upgradeSkill.oldPosition then
                    task.wait(0.2)
                    local char = LocalPlayer.Character
                    if char then
                        local root = char:FindFirstChild("HumanoidRootPart")
                        if root then
                            root.CFrame = CFrame.new(NexusState.upgradeSkill.oldPosition)
                            NexusState.upgradeSkill.oldPosition = nil
                            NexusState.upgradeSkill.teleported = false
                        end
                    end
                end

                if success then
                    NexusLib:Notify({ Title = "Upgrade Skill", Message = "Upgraded " .. selectedSkill .. "!", Duration = 2 })
