            Default = "Instant",
            Callback = function(value) NexusState.craftRodMethod = value end
        })

        local function checkRodMaterials(rodName)
            local recipe = ROD_RECIPES[rodName]
            if not recipe then return false, "Recipe not found for " .. rodName end
            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))
            if not userData then return false, "Player data not found" end
            local inventory = userData:FindFirstChild("Inventory")
            if not inventory then return false, "Inventory not found" end
            local fishCount = {}
            for _, req in ipairs(recipe) do fishCount[req.name] = 0 end
            for _, item in pairs(inventory:GetChildren()) do
                local fishName, weight, count = parseCraftFishEntry(item)
                if fishName and fishName ~= "" then
                    local req = nil
                    for _, r in ipairs(recipe) do
                        if r.name == fishName then req = r; break end
                    end
                    if req then
                        if weight and weight >= req.minKg and weight <= req.maxKg then
                            fishCount[req.name] = fishCount[req.name] + count
                        end
                    end
                end
            end
            local missing = {}
            for _, req in ipairs(recipe) do
                local count = fishCount[req.name] or 0
                if count < 1 then
                    table.insert(missing, req.name .. " (need 1, have " .. count .. ")")
                end
            end
            if #missing > 0 then
                return false, "Missing materials: " .. table.concat(missing, ", ")
            end
            return true, "All materials ready!"
        end

        local function craftRod()
            local ok, msg = checkRodMaterials(selectedRod)
            if not ok then
                NexusLib:Notify({ Title = "Craft Rod", Message = msg, Duration = 4 })
                return
            end
            local method = NexusState.craftRodMethod or "Instant"
            local teleported = false
            if method == "Teleport" then
                local npc = Workspace:FindFirstChild("NPC")
                if npc then
                    local buyRod = npc:FindFirstChild("BuyFishingRod")
                    if buyRod then
                        local biaoDi = buyRod:FindFirstChild("Biao Di")
                        if typeof(biaoDi) == "Instance" and biaoDi:IsA("Model") then
                            local hrp = biaoDi:FindFirstChild("HumanoidRootPart")
                            if hrp then
                                local char = LocalPlayer.Character
                                if char then
                                    local root = char:FindFirstChild("HumanoidRootPart")
                                    if root then
                                        NexusState.lastCraftPosition = root.Position
                                        root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))
                                        teleported = true
                                        task.wait(0.3)
                                    end
                                end
                            end
                        end
                    end
                end
            end
            local success, err = pcall(function()
                Events.CraftRod:FireServer(selectedRod)
            end)
            if success then
                NexusLib:Notify({ Title = "Craft Rod", Message = "Crafted " .. selectedRod .. " successfully!", Duration = 2 })
            else
                NexusLib:Notify({ Title = "Craft Rod", Message = "Failed: " .. tostring(err), Duration = 2 })
            end
            if teleported and NexusState.lastCraftPosition then
                task.wait(0.3)
                local char = LocalPlayer.Character
                if char then
                    local root = char:FindFirstChild("HumanoidRootPart")
                    if root then
                        root.CFrame = CFrame.new(NexusState.lastCraftPosition)
                        NexusState.lastCraftPosition = nil
                    end
                end
            end
        end

        CraftRodSection:CreateButton({ Name = "Craft rod now", Callback = craftRod })
        local autoCraftRodToggle = Cfg.register(CraftRodSection:CreateToggle(Cfg.wrap("Toggle", "Auto craft selected rod", {
            Name = "Auto craft selected rod",
