                        end
                    end)
                else
                    if NexusState.autoCraftRodThread then
                        task.cancel(NexusState.autoCraftRodThread)
                        NexusState.autoCraftRodThread = nil
                    end
                end
            end
        })), "Toggle", "Auto craft selected rod", {
