                        if learnSkill then
                            local sageYijiu = learnSkill:FindFirstChild("Sage Yijiu")
                            if typeof(sageYijiu) == "Instance" and sageYijiu:IsA("Model") then
                                local hrp = sageYijiu:FindFirstChild("HumanoidRootPart")
