            Callback = function(value) NexusState.craftBaitMethod = value end
        })

        local BAIT_RECIPES = {
            ["Rainbow Bait"] = {
                {name = "Colossal Tigerfish", minKg = 3000000, maxKg = 6000000},
                {name = "Heavenpiercer Turtle", minKg = 3000000, maxKg = 6000000},
                {name = "Golden Guardian Fish", minKg = 1000000, maxKg = 3000000},
                {name = "Crimson Electric Eel", minKg = 3000000, maxKg = 4000000},
            },
            ["Frost Bait"] = {
                {name = "Frost Kingfish", minKg = 4000000, maxKg = 7000000},
                {name = "Ascended Perch", minKg = 900000, maxKg = 1000000},
                {name = "Primordial Kunfish Overlord", minKg = 1000000, maxKg = 1600000},
                {name = "Warbringer Shark", minKg = 500000, maxKg = 800000},
            },
            ["Nameless Bait"] = {
                {name = "Mountain Fish", minKg = 1000000, maxKg = 5000000},
                {name = "Tiger Mirefish", minKg = 1000000, maxKg = 3000000},
                {name = "Mirage Lanternfish", minKg = 3000000, maxKg = 5000000},
                {name = "Octoparasitic Fish", minKg = 3000000, maxKg = 5000000},
            }
        }

        local function checkMaterials(baitName, quantity)
            local recipe = BAIT_RECIPES[baitName]
            if not recipe then return false, "No recipe found for " .. baitName end
            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))
            if not userData then return false, "Player data not found" end
            local inventory = userData:FindFirstChild("Inventory")
            if not inventory then return false, "Invento]=],[=[
ry not found" end
            local fishCount = {}
            for _, req in ipairs(recipe) do fishCount[req.name] = 0 end
            for _, item in pairs(inventory:GetChildren()) do
                local fishName, weight, count = parseCraftFishEntry(item)
                if fishName and fishName ~= "" then
                    local req = nil
                    for _, r in ipairs(recipe) do
                        if r.name == fishName then req = r; break end
                    end
                    if req then
                        if weight and weight >= req.minKg and weight <= req.maxKg then
                            fishCount[req.name] = fishCount[req.name] + count
                        end
                    end
                end
            end
            local missing = {}
            for _, req in ipairs(recipe) do
                local count = fishCount[req.name] or 0
                if count < quantity then
                    table.insert(missing, req.name .. " (can " .. quantity .. ", co " .. count .. ")")
                end
            end
            if #missing > 0 then
                return false, "Missing materials: " .. table.concat(missing, ", ")
            end
            return true, "Materials are sufficient!"
        end

        local function craftBait()
            local qty = NexusState.craftBaitQuantity
            local ok, msg = checkMaterials(NexusState.craftBaitName, qty)
            if not ok then
                NexusLib:Notify({ Title = "Craft Bait", Message = msg, Duration = 4 })
                return
            end
            local method = NexusState.craftBaitMethod or "Instant"
            local teleported = false
            if method == "Teleport" then
                local npc = Workspace:FindFirstChild("NPC")
                if npc then
                    local buyBait = npc:FindFirstChild("BuyBait")
                    if buyBait then
                        local children = buyBait:GetChildren()
                        if #children >= 5 then
                            local targetModel = children[5]
                            if typeof(targetModel) == "Instance" and targetModel:IsA("Model") then
                                local hrp = targetModel:FindFirstChild("HumanoidRootPart")
                                if hrp then
                                    local char = LocalPlayer.Character
                                    if char then
                                        local root = char:FindFirstChild("HumanoidRootPart")
                                        if root then
                                            NexusState.lastCraftBaitPosition = root.Position
                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))
                                            teleported = true
                                            task.wait(0.3)
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
            local success, err = pcall(function()
                Events.CraftBait:FireServer(NexusState.craftBaitName, qty)
            end)
            if success then
                NexusLib:Notify({ Title = "Craft Bait", Message = "Crafted " .. qty .. "x " .. NexusState.craftBaitName, Duration = 2 })
            else
                NexusLib:Notify({ Title = "Craft Bait", Message = "Failed: " .. tostring(err), Duration = 2 })
            end
            if teleported and NexusState.lastCraftBaitPosition then
                task.wait(0.3)
                local char = LocalPlayer.Character
                if char then
                    local root = char:FindFirstChild("HumanoidRootPart")
                    if root then
                        root.CFrame = CFrame.new(NexusState.lastCraftBaitPosition)
                        NexusState.lastCraftBaitPosition = nil
                    end
                end
            end
        end

        local autoCraftToggle = Cfg.register(CraftSection:CreateToggle(Cfg.wrap("Toggle", "Auto craft bait", {
            Name = "Auto craft bait",
            Default = false,
            Callback = function(value)
                NexusState.autoCraftRunning = value
                if value then
                    if NexusState.autoCraftThread then
                        task.cancel(NexusState.autoCraftThread)
                        NexusState.autoCraftThread = nil
                    end
                    NexusState.autoCraftThread = task.spawn(function()
                        while NexusState.autoCraftRunning do
                            pcall(craftBait)
                            task.wait(5)
                        end
                    end)
                else
                    if NexusState.autoCraftThread then
                        task.cancel(NexusState.autoCraftThread)
                        NexusState.autoCraftThread = nil
                    end
                end
            end
        })), "Toggle", "Auto craft bait", {
            Name = "Auto craft bait",
