-- ===== QUESTS TAB =====
-- ============================================================
do
    local QuestsTab = Window:CreateTab("Quests")

    -- Teleport to Ticket Quest Giver, open dialogue, fire action, go back.
    -- StartDialogue first: server ignores ChooseDialogueOption with no open dialogue.
    NexusState.ticketLastFire = NexusState.ticketLastFire or 0
    NexusState.ticketFailCount = NexusState.ticketFailCount or 0
    local function ticketGoFire(action)
        if _G and _G.Events then
            local sd = _G.Events:FindFirstChild("StartDialogue")
            local cd = _G.Events:FindFirstChild("ChooseDialogueOption")
            if not sd or not cd then return false end
        end
        local giver = nil
        pcall(function()
            local npc = Workspace:FindFirstChild("NPC")
            local npcFunc = npc and npc:FindFirstChild("Function")
            giver = npcFunc and npcFunc:FindFirstChild("Ticket Quest Giver")
        end)
        if not giver then return false end
        local extraData = { giver }
        local charNow = LocalPlayer.Character
        local root = charNow and charNow:FindFirstChild("HumanoidRootPart")
        local giverPos = nil
        pcall(function()
            if typeof(giver) == "Instance" and typeof(giver) == "Instance" and giver:IsA("Model") then
                local hrp = giver:FindFirstChild("HumanoidRootPart")
                if hrp then
                    giverPos = hrp.Position
                elseif giver.PrimaryPart then
                    giverPos = giver.PrimaryPart.Position
                else
                    giverPos = giver:GetPivot().Position
                end
            elseif typeof(giver) == "Instance" and typeof(giver) == "Instance" and giver:IsA("BasePart") then
                giverPos = giver.Position
            end
        end)
        local origCF = root and root.CFrame
        if root and giverPos then
            pcall(function() root.CFrame = CFrame.new(giverPos + Vector3.new(0, 3, 0)) end)
            task.wait(0.45)
        end
        pcall(function()
            Events.StartDialogue:FireServer("Ticket Quest Giver", giver)
        end)
        task.wait(0.25)
        pcall(function()
            Events.ChooseDialogueOption:FireServer("Ticket Quest Giver", 1, action, ]=],[=[
extraData)
        end)
        task.wait(0.2)
        if origCF and root and root.Parent then
            pcall(function() root.CFrame = origCF end)
        end
        return true
    end

    -- ===== AUTO CLAIM TICKET QUEST =====
    do
        local ClaimSection = QuestsTab:CreateSection("Auto Claim Ticket Quest")
        local questTypes = {"Easy Quest", "Hard Quest"}
        local selectedQuest = questTypes[1]

        local function HasActiveQuest()
            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))
            if not userData then return false end
            local quest = userData:FindFirstChild("Quest")
            if not quest then return false end
            local main = quest:FindFirstChild("Main")
            if not main then return false end
            for _, child in pairs(main:GetChildren()) do
                if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("Folder") then
                    local name = child.Name
                    if name == "Easy Ticket Quest" or name == "Hard Ticket Quest" then
                        return true
                    end
                end
            end
            return false
        end

        local claimDropdown = Cfg.register(ClaimSection:CreateDropdown(Cfg.wrap("Dropdown", "Select Quest Type", {
            Name = "Select Quest Type",
            Options = questTypes,
            Default = selectedQuest,
            Callback = function(value) selectedQuest = value end
        })), "Dropdown", "Select Quest Type", {
            Name = "Select Quest Type",
            Options = questTypes,
            Default = selectedQuest,
            Callback = function(value) selectedQuest = value end
        })

        local autoClaimToggle = Cfg.register(ClaimSection:CreateToggle(Cfg.wrap("Toggle", "Auto Claim Ticket Quest (Fast)", {
            Name = "Auto Claim Ticket Quest (Fast)",
            Default = false,
            Callback = function(value)
                NexusState.autoClaimRunning = value
                if value then
                    if NexusState.autoClaimThread then
                        task.cancel(NexusState.autoClaimThread)
                        NexusState.autoClaimThread = nil
                    end
                    NexusState.autoClaimThread = task.spawn(function()
                        while NexusState.autoClaimRunning do
                            pcall(function()
                                if not HasActiveQuest() then
                                    if tick() - (NexusState.ticketLastFire or 0) < 3 then return end
                                    NexusState.ticketLastFire = tick()
                                    local selAction = nil
                                    if selectedQuest == "Easy Quest" then
                                        selAction = "EasyAcceptQuest"
                                    else
                                        selAction = "HardAcceptQuest"
                                    end
                                    if ticketGoFire(selAction) and HasActiveQuest() then
                                        NexusState.ticketFailCount = 0
                                        NexusLib:Notify({
                                            Title = "Quest",
                                            Message = "Claimed " .. selectedQuest,
                                            Duration = 2
                                        })
                                    else
                                        NexusState.ticketFailCount = (NexusState.ticketFailCount or 0) + 1
                                        if NexusState.ticketFailCount == 5 then
                                            NexusLib:Notify({ Title = "Quest", Message = "Claim failed 5 times. Check NPC or quest type.", Duration = 4 })
                                        end
                                    end
                                else
                                    NexusState.ticketFailCount = 0
                                end
                            end)
                            task.wait(0.5)
                        end
                    end)
                else
                    if NexusState.autoClaimThread then
                        task.cancel(NexusState.autoClaimThread)
                        NexusState.autoClaimThread = nil
                    end
                    NexusState.ticketFailCount = 0
                    NexusLib:Notify({ Title = "Quest", Message = "Auto claim stopped", Duration = 2 })
                end
            end
        })), "Toggle", "Auto Claim Ticket Quest (Fast)", {
            Name = "Auto Claim Ticket Quest (Fast)",
            Default = false,
            Callback = function(value)
                NexusState.autoClaimRunning = value
                if value then
                    if NexusState.autoClaimThread then
                        task.cancel(NexusState.autoClaimThread)
                        NexusState.autoClaimThread = nil
                    end
                    NexusState.autoClaimThread = task.spawn(function()
                        while NexusState.autoClaimRunning do
                            pcall(function()
                                if not HasActiveQuest() then
                                    if tick() - (NexusState.ticketLastFire or 0) < 3 then return end
                                    NexusState.ticketLastFire = tick()
                                    local selAction = nil
                                    if selectedQuest == "Easy Quest" then
                                        selAction = "EasyAcceptQuest"
                                    else
                                        selAction = "HardAcceptQuest"
                                    end
                                    if ticketGoFire(selAction) and HasActiveQuest() then
                                        NexusState.ticketFailCount = 0
                                        NexusLib:Notify({
                                            Title = "Quest",
                                            Message = "Claimed " .. selectedQuest,
                                            Duration = 2
                                        })
                                    else
                                        NexusState.ticketFailCount = (NexusState.ticketFailCount or 0) + 1
                                        if NexusState.ticketFailCount == 5 then
                                            NexusLib:Notify({ Title = "Quest", Message = "Claim failed 5 times. Check NPC or quest type.", Duration = 4 })
                                        end
                                    end
                                else
                                    NexusState.ticketFailCount = 0
                                end
                            end)
