                    end)
                else
                    if NexusState.autoClaimThread then
                        task.cancel(NexusState.autoClaimThread)
                        NexusState.autoClaimThread = nil
                    end
                    NexusState.ticketFailCount = 0
                    NexusLib:Notify({ Title = "Quest", Message = "Auto claim stopped", Duration = 2 })
                end
            end
        })
    end

    -- ===== DAILY QUESTS =====
    do
        local DailySection = QuestsTab:CreateSection("Daily Quests")
        local dailyRunning = false
        local dailyThread = nil

        local function teleportToIsland(island)
            if not island then return false end
            local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            if not hrp then return false end
            local target = island.cframe.Position + Vector3.new(0, 5, 0)
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
            hrp.CFrame = CFrame.new(target)
            return true
        end

        local function doDailyQuest()
            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))
            if not userData then
                NexusLib:Notify({ Title = "Daily Quest", Message = "User data not found!", Duration = 2 })
                return
            end
            local dailyFolder = userData:FindFirstChild("Quest") and userData.Quest:FindFirstChild("Daily")
            if not dailyFolder then
                NexusLib:Notify({ Title = "Daily Quest", Message = "Daily quest folder not found!", Duration = 2 })
                return
            end
            local questFolders = {}
            for _, child in pairs(dailyFolder:GetChildren()) do
                if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("Folder") then
                    table.insert(questFolders, child)
                end
            end
            if #questFolders == 0 then
                NexusLib:Notify({ Title = "Daily Quest", Message = "No daily quests available!", Duration = 2 })
                return
            end
            local selectedFolder = questFolders[math.random(1, #questFolders)]
            local questId = selectedFolder.Name
            local progression = selectedFolder:FindFirstChild("Progression")
            local questType = selectedFolder:FindFirstChild("QuestType")
            if not progression or not questType then
                NexusLib:Notify({ Title = "Daily Quest", Message = "Missing Progression or QuestType in quest " .. questId, Duration = 2 })
                return
            end
            local currentProgress = (typeof(progression) == "Instance" and progression:IsA("NumberValue")) and progression.Value or 0
            local qType = (typeof(questType) == "Instance" and questType:IsA("StringValue")) and questType.Value or ""

            NexusLib:Notify({
                Title = "Daily Quest",
                Message = "Selected quest " .. questId .. " | Type: " .. qType .. " | Progress: " .. currentProgress,
                Duration = 4
            })

            if qType == "PlayTime" then
                NexusLib:Notify({ Title = "Daily Quest", Message = "PlayTime quest: just play for 30 minutes!", Duration = 3 })
                return
            end

            if qType == "Fishing" then
                local island = getRecommendedIsland()
                if not island then
                    NexusLib:Notify({ Title = "Daily Quest", Message = "No suitable island found!", Duration = 2 })
                    return
                end
                if not teleportToIsland(island) then
                    NexusLib:Notify({ Title = "Daily Quest", Message = "Teleport failed!", Duration = 2 })
                    return
                end
                enableBasicFishing()
                Fishing.Flags.AutoFarmBoss = false
                Fishing.Flags.AutoFarmSecretBoss = false
                NexusLib:Notify({ Title = "Daily Quest", Message = "Fishing daily started on " .. island.name, Duration = 2 })
                while dailyRunning do
                    local newProgress = selectedFolder:FindFirstChild("Progression")
                    if typeof(newProgress) == "Instance" and newProgress:IsA("NumberValue") then
                        if newProgress.Value >= 100 then
                            NexusLib:Notify({ Title = "Daily Quest", Message = "Fishing daily completed!", Duration = 3 })
                            break
                        end
                    end
                    task.wait]=],[=[
(2)
                end
            elseif qType == "BossQuest" then
                local island = getRecommendedIsland()
                if not island then
                    NexusLib:Notify({ Title = "Daily Quest", Message = "No suitable island found!", Duration = 2 })
                    return
                end
                if not teleportToIsland(island) then
                    NexusLib:Notify({ Title = "Daily Quest", Message = "Teleport failed!", Duration = 2 })
                    return
                end
                enableBasicFishing()
                Fishing.Flags.AutoFarmBoss = true
                Fishing.Flags.AutoFarmSecretBoss = false
                NexusLib:Notify({ Title = "Daily Quest", Message = "Boss daily started on " .. island.name, Duration = 2 })
                while dailyRunning do
                    local newProgress = selectedFolder:FindFirstChild("Progression")
                    if typeof(newProgress) == "Instance" and newProgress:IsA("NumberValue") then
                        if newProgress.Value >= 10 then
                            NexusLib:Notify({ Title = "Daily Quest", Message = "Boss daily completed!", Duration = 3 })
                            break
                        end
                    end
                    task.wait(2)
                end
            elseif qType == "Bait" then
                NexusLib:Notify({ Title = "Daily Quest", Message = "Bait daily: buying Basic Bait...", Duration = 2 })
                local buyEvent = Events:FindFirstChild("BuyBait")
                if not buyEvent then
                    NexusLib:Notify({ Title = "Daily Quest", Message = "BuyBait remote not found!", Duration = 2 })
                    return
                end
                while dailyRunning do
                    local newProgress = selectedFolder:FindFirstChild("Progression")
                    if typeof(newProgress) == "Instance" and newProgress:IsA("NumberValue") then
                        if newProgress.Value >= 25 then
                            NexusLib:Notify({ Title = "Daily Quest", Message = "Bait daily completed!", Duration = 3 })
                            break
                        end
                    end
                    pcall(function() buyEvent:FireServer("Basic Bait", 1) end)
                    task.wait(0.5)
                end
            else
                NexusLib:Notify({ Title = "Daily Quest", Message = "Unknown quest type: " .. qType, Duration = 2 })
            end
            restoreRoutineFlags()
        end

        -- Toggle Auto Do Daily Quest
        local autoDailyToggle = Cfg.register(DailySection:CreateToggle(Cfg.wrap("Toggle", "Auto Do Daily Quest", {
            Name = "Auto Do Daily Quest",
            Default = false,
            Callback = function(value)
                dailyRunning = value
                if value then
                    if dailyThread then
                        task.cancel(dailyThread)
                        dailyThread = nil
                    end
                    dailyThread = task.spawn(function()
                        while dailyRunning do
                            pcall(doDailyQuest)
                            if dailyRunning then
                                task.wait(5)
                            end
                        end
                    end)
                    NexusLib:Notify({ Title = "Daily Quest", Message = "Auto Daily started!", Duration = 2 })
                else
                    if dailyThread then
                        task.cancel(dailyThread)
                        dailyThread = nil
                    end
                    restoreRoutineFlags()
                    NexusLib:Notify({ Title = "Daily Quest", Message = "Auto Daily stopped", Duration = 2 })
                end
            end
        })), "Toggle", "Auto Do Daily Quest", {
            Name = "Auto Do Daily Quest",
            Default = false,
            Callback = function(value)
                dailyRunning = value
                if value then
                    if dailyThread then
                        task.cancel(dailyThread)
                        dailyThread = nil
                    end
                    dailyThread = task.spawn(function()
                        while dailyRunning do
                            pcall(doDailyQuest)
                            if dailyRunning then
                                task.wait(5)
                            end
                        end
                    end)
                    NexusLib:Notify({ Title = "Daily Quest", Message = "Auto Daily started!", Duration = 2 })
                else
                    if dailyThread then
                        task.cancel(dailyThread)
                        dailyThread = nil
                    end
                    restoreRoutineFlags()
                    NexusLib:Notify({ Title = "Daily Quest", Message = "Auto Daily stopped", Duration = 2 })
                end
            end
        })

        -- ===== CLAIM DAILY REWARDS BUTTON =====
        DailySection:CreateButton({
            Name = "Claim Daily Rewards",
            Callback = function()
                local dailyRewardEvent = Events:FindFirstChild("DailyReward")
                if not dailyRewardEvent then
                    NexusLib:Notify({ Title = "Daily Rewards", Message = "DailyReward remote not found!", Duration = 3 })
                    return
                end
                NexusLib:Notify({ Title = "Daily Rewards", Message = "Claiming all 7 daily rewards...", Duration = 2 })
                task.spawn(function()
                    for i = 1, 7 do
                        pcall(function()
                            dailyRewardEvent:FireServer(i)
                        end)
                        task.wait(0.5)
                    end
                    NexusLib:Notify({ Title = "Daily Rewards", Message = "All 7 daily rewards claimed!", Duration = 3 })
                end)
            end
        })
    end

    -- ===== MATERIAL FARMING =====
    do
        local MaterialSection = QuestsTab:CreateSection("Material Farming")
        local MatFishingAreaRarity
        pcall(function()
            MatFishingAreaRarity = require(Info.FishingAreaRarity)
        end)
        if not MatFishingAreaRarity then
            MatFishingAreaRarity = {
                ["Beginning Isle"] = {}, ["Bamboo Isle"] = {}, ["Fallout Isle"] = {},
                ["Sovereign Isle"] = {}, ["Perch Isle"] = {}, ["Frost Isle"] = {},
                ["Coconut Isle"] = {}, ["Amber Isle"] = {}, ["Battlefield Isle"] = {},
                ["Mistpeak Isle"] = {}, ["Exclusive"] = {}, ["Secret Boss"] = {},
            }
        end

        local matIslandDisplayNames = {
            ["Beginning Isle"] = "Island 1", ["Bamboo Isle"] = "Island 2", ["Fallout Isle"] = "Island 3",
            ["Sovereign Isle"] = "Island 4", ["Perch Isle"] = "Island 5", ["Frost Isle"] = "Island 6",
            ["Coconut Isle"] = "Island 7", ["Amber Isle"] = "Island 8", ["Battlefield Isle"] = "Island 9",
            ["Mistpeak Isle"] = "Island 10", ["Exclusive"] = "Exclusive", ["Secret Boss"] = "Secret Boss"
        }
        local matIslandOrder = {
            "Beginning Isle","Bamboo Isle","Fallout Isle","Sovereign Isle","Perch Isle","Frost Isle",
            "Coconut Isle","Amber Isle","Battlefield Isle","Mistpeak Isle","Exclusive","Secret Boss"
        }
        local matIslandNameToIsland = {}
        for _, island in ipairs(NexusState.islands) do matIslandNameToIsland[island.name] = island end
        for rarityName, displayName in pairs(matIslandDisplayNames) do
            for _, island in ipairs(NexusState.islands) do
                if island.name == displayName then matIslandNameToIsland[rarityName] = island end
            end
        end

        local function matGetIslandsForFish(fishName)
            local result = {}
            for _, islandName in ipairs(matIslandOrder) do
                local fishList = MatFishingAreaRarity[islandName]
                if fishList and fishList[fishName] then table.insert(result, islandName) end
            end
            return result
        end

        local function matGetMaterialCount(fishName, minKg, maxKg)
            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))
            if not userData then return 0 end
            local inventory = userData:FindFirstChild("Inventory")
            if not inventory then return 0 end
            local count = 0
            for _, item in pairs(inventory:GetChildren()) do
                if item.Name == fishName then
                    local weightString = nil
                    if typeof(item) == "Instance" and typeof(item) == "Instance" and item:IsA("StringValue") then
                        local parts = {}
                        for part in string.gmatch(item.Value, "[^|]+") do table.insert(parts, part) end
                        if #parts >= 2 then weightString = parts[2]:gsub("^%s+", ""):gsub("%s+$", "") end
                    elseif typeof(item) == "Instance" and typeof(item) == "Instance" and item:IsA("NumberValue") or item:IsA("IntValue") then
                        weightString = tostring(item.Value)
                    end
                    if weightString then
                        local weight = tonumber(weightString)
                        if weight and weight >= minKg and weight <= maxKg then
                            count = count + 1
                        end
                    end
                end
            end
            return count
        end

        local function matTeleportToIsland(islandName)
            local island = matIslandNameToIsland[islandName]
            if not island then return false end
            local char = LocalPlayer.Character
            if not char then return false end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if hrp then
                hrp.AssemblyLinearVelocity = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
                hrp.CFrame = CFrame.new(island.cframe.Position) + Vector3.new(0, 5, 0)
                return true
            end
            return false
        end

        local function matGetWeather()
            local mg = LocalPlayer:FindFirstChild("PlayerGui") and LocalPlayer.PlayerGui:FindFirstChild("MainGui")
            if mg then
                local info = mg:FindFirstChild("Info")
                local infoFrame = info and info:FindFirstChild("Info")
                local weatherFrame = infoFrame and infoFrame:FindFirstChild("Weather")
                local val = weatherFrame and weatherFrame:FindFirstChild("Value")
                if val and typeof(val) == "Instance" then
                    local text = ((typeof(val) == "Instance" and val:IsA("TextLabel") and val.Text or val.Value))
                    return (text:gsub("Weather:%s*", ""))
                end
            end
            return "Clear"
        end

        local function matCancelFishing()
            local char = LocalPlayer.Character
            if not char then return end
            if not char:GetAttribute("Fishing") then return end
