    -- ===== Target island resolver =====
    local function getTargetIsland()
        if selectedIslandMode == "Auto Select Island" then
            return getRecommendedIsland()
        else
            for _, island in ipairs(NexusState.islands) do
                if island.name == selectedIslandName then
                    return island
                end
            end
            return nil
        end
    end

    -- ===== parse / getCurrentQuestProgress helpers (unchanged) =====
    local function parseQuestString(str)
        if not str or str == "" then return nil, nil end
        local parts = {}
        for part in string.gmatch(str, "[^,]+") do table.insert(parts, part) end
        if #parts >= 3 then
            local target = nil
            local typ = nil
            if string.find(parts[1], "Boss") then
                target = tonumber(parts[3])
                typ = parts[1]
            else
                target = tonumber(parts[2])
                typ = parts[3]
            end
            if target and typ then return target, typ end
        end
        return nil, nil
    end

    local function getCurrentQuestProgress()
        local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))
        if not userData then return nil end
        local quest = userData:FindFirstChild("Quest")
        if not quest then return nil end
        local main = quest:FindFirstChild("Main")
        if not main then return nil end
        for _, folder in pairs(main:GetChildren()) do
            if typeof(folder) == "Instance" and typeof(folder) == "Instance" and folder:IsA("Folder") and (folder.Name == "Easy Ticket Quest" or folder.Name == "Hard Ticket Quest") then
                local current = nil
                local target = nil
                local typ = nil
                local questName = folder.Name
                for _, child in pairs(folder:GetChildren()) do
                    if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("NumberValue") or child:IsA("IntValue") then
                        if child.Name == "1" then
                            current = child.Value
                        end
                    end
                end
                local objective = folder:FindFirstChild("Objective")
                if objective then
                    for _, child in pairs(objective:GetChildren()) do
                        if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("StringValue") and child.Name == "1" then
                            local val = child.Value
                            if val and val ~= "" then
                                NexusState.ticketObjectiveText = tostring(val)
                                local t, ty = parseQuestString(val)
                                if t and ty then
                                    target = t
                                    typ = ty
                                end
                            end
                        end
                    end
                end
                if current and target and typ then
                    return current, target, questName, typ
                end
            end
        end
        return nil
    end

    local function updateQuestStatus()
        local current, target, questName, typ = getCurrentQuestProgress()
        if current and target and questName then
            NexusState.ticketTargetCount = target
            NexusState.ticketCurrentCount = current
            NexusState.ticketQuestActive = true
            if current >= target then
                if not NexusState.ticketQuestClaimed then
                    NexusLib:Notify({ Title = "Quest", Message = "Complete! Claiming reward...", Duration = 2 })
                    -- TP to NPC, turn in with retries, chain next quest right away.
                    local turnedIn = false
                    for _ = 1, 5 do
                        if ticketGoFire("Quest") then
                            for _ = 1, 6 do
                                task.wait(0.15)
                                if not getCurrentQuestProgress() then
                                    turnedIn = true
                                    break
                                end
                            end
                        end
                        if turnedIn then break end
                        task.wait(0.2)
                    end
                    if turnedIn then
                        NexusState.ticketQuestClaimed = true
                        NexusState.ticketLastFire = 0
                        NexusState.ticketFailCount = 0
                        NexusState.isDoingUseBaitQuest = false
                        disableAllFishing()
                        NexusState.ticketQuestActive = false
                        NexusLib:Notify({ Title = "Quest", Message = "Turned in. Claim toggle takes next quest.", Duration = 3 })
                    else
                        NexusLib:Notify({ Title = "Quest", Message = "Turn-in failed, retrying...", Duration = 2 })
                    end
                end
                NexusState.isDoingUseBaitQuest = false
                Fishing.Flags.AutoSkill = false
                Fishing.Flags.AutoSkillCheck = false
                NexusState.ticketQuestActive = false
                return
            end
            NexusState.ticketQuestClaimed = false
            
            -- Teleport to target island (manual choice wins)
            local targetIsland = getTargetIsland()
            if targetIsland then
                local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                if hrp then
                    local targetPos = targetIsland.cframe.Position + Vector3.new(0, 5, 0)
                    if (hrp.Position - targetPos).Magnitude > 25 and (tick() - (NexusState.ticketLastTele or 0) > 3) then
                        NexusState.ticketLastTele = tick()
                        safeTeleport(hrp, CFrame.new(targetPos))
                    end
                end
            end
            
                        local need = string.lower(tostring(typ or "") .. " " .. tostring(NexusState.ticketObjectiveText or ""))
            local function needHas(...)
                for _, k in ipairs({...}) do
                    if string.find(need, k, 1, true) then return true end
                end
                return false
            end
            NexusState.isDoingUseBaitQuest = false
            -- Ticket pool: use bait / catch fish / heavy fish (1.5M) / use skill.
            -- No boss quests here, so boss words inside fish names must not trigger boss farm.
            if needHas("usebait", "use bait", "bait") then
                NexusState.isDoingUseBaitQuest = true
                enableBasicFishing()
                Fishing.Flags.AutoFarmBoss = false
                Fishing.Flags.AutoFarmSecretBoss = false
                Fishing.Flags.AnchorLock = true
                Fishing.Flags.AutoSkill = true
                Fishing.Flags.AutoSkillCheck = true
                MiscFlags.AutoBuy = true
                local buyable = GetBuyableBaits()
                local found = false
                for _, name in ipairs(buyable) do
                    if name == "Basic Bait" then
                        NexusState.selectedBait = name
                        found = true
                        break
                    end
                end
                if not found then
                    NexusState.selectedBa]=],[=[
it = buyable[1] or "No bait available"
                end
                MiscFlags.AutoEquipBait = true
            elseif needHas("skill") then
                enableBasicFishing()
                Fishing.Flags.AutoFarmBoss = false
                Fishing.Flags.AutoFarmSecretBoss = false
                Fishing.Flags.AutoSkill = true
                Fishing.Flags.AutoSkillCheck = true
                Fishing.Flags.AnchorLock = true
            elseif needHas("weight", "kg", "heavy", "1.5m", "1,5m", "1500000") then
                enableBasicFishing()
                Fishing.Flags.AutoFarmBoss = false
                Fishing.Flags.AutoFarmSecretBoss = false
                pcall(function() Events.UpdateFishProgression:FireServer() end)
            elseif needHas("fish", "catch", "fishing") then
                enableBasicFishing()
                Fishing.Flags.AutoFarmBoss = false
                Fishing.Flags.AutoFarmSecretBoss = false
                pcall(function() Events.UpdateFishProgression:FireServer() end)
            else
                enableBasicFishing()
                Fishing.Flags.AutoFarmBoss = false
                Fishing.Flags.AutoFarmSecretBoss = false
            end
        else
            if NexusState.ticketQuestActive then
                NexusState.ticketQuestActive = false
                NexusState.ticketTargetCount = 0
                NexusState.ticketCurrentCount = 0
                NexusState.isDoingUseBaitQuest = false
                Fishing.Flags.AutoSkill = false
                Fishing.Flags.AutoSkillCheck = false
                disableAllFishing()
            end
            NexusState.isDoingUseBaitQuest = false
            NexusState.ticketQuestClaimed = false
            NexusState.ticketLastFire = 0
            NexusState.ticketFailCount = 0
            NexusState.ticketObjectiveText = nil
        end
    end

    local function startAutoDoLoop()
        if NexusState.autoDoThread then return end
        NexusState.autoDoThread = task.spawn(function()
            while NexusState.autoDoRunning do
                pcall(updateQuestStatus)
                task.wait(1)
            end
            NexusState.autoDoThread = nil
        end)
    end

