                                local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                                if hrp then
                                    local targetPos = bestIsland.cframe.Position + Vector3.new(0, 5, 0)
                                    safeTeleport(hrp, CFrame.new(targetPos))
                                    lastTeleportedPowerIsland = bestIsland.name
                                    NexusLib:Notify({
                                        Title = "Recommend",
                                        Message = "Teleported to " .. bestIsland.name .. " (sky) (Power " .. (bestIsland.power or 0) .. ")",
                                        Duration = 2
                                    })
                                end
                            end
                        end)
                        task.wait(3)
                    end
                end)
            else
                if NexusState.autoRecommendThread then
                    task.cancel(NexusState.autoRecommendThread)
                    NexusState.autoRecommendThread = nil
                end
                lastTeleportedPowerIsland = nil
            end
        end
    })
