do
    local UpgradeTab = Window:CreateTab("Upgrade")
    local UpgradeSection = UpgradeTab:CreateSection("Character Upgrade")

    local optionsList = {"Cash", "Level", "Crystal", "Ticket"}
    NexusState.UpgradeCharacter = Events:WaitForChild("UpgradeCharacter")

    local multiDropdown = Cfg.register(UpgradeSection:CreateMultiDropdown(Cfg.wrap("MultiDropdown", "Select 2 upgrade options", {
        Name = "Select 2 upgrade options",
        Options = optionsList,
        Default = NexusState.selectedOptions or {"Cash", "Level"},
        Callback = function(values)
            if #values > 2 then
                NexusLib:Notify({ Title = "Upgrade", Message = "You can only select 2 options!", Duration = 2 })
                local newValues = {}
                for i = #values - 1, #values do table.insert(newValues, values[i]) end
                NexusState.selectedOptions = newValues
            else
                NexusState.selectedOptions = values
            end
        end
    })), "MultiDropdown", "Select 2 upgrade options", {
        Name = "Select 2 upgrade options",
        Options = optionsList,
        Default = NexusState.selectedOptions or {"Cash", "Level"},
        Callback = function(values)
            if #values > 2 then
                NexusLib:Notify({ Title = "Upgrade", Message = "You can only select 2 options!", Duration = 2 })
                local newValues = {}
                for i = #values - 1, #values do table.insert(newValues, values[i]) end
                NexusState.selectedOptions = newValues
            else
                NexusState.selectedOptions = values
            end
        end
    })

    local upgradeCharMethodDropdown = Cfg.register(UpgradeSection:CreateDropdown(Cfg.wrap("Dropdown", "Upgrade Method", {
        Name = "Upgrade Method",
        Options = {"Instant", "Teleport"},
        Default = NexusState.upgradeCharacter.method or "Instant",
        Callback = function(value) NexusState.upgradeCharacter.method = value end
    })), "Dropdown", "Upgrade Method", {
        Name = "Upgrade Method",
        Options = {"Instant", "Teleport"},
        Default = NexusState.upgradeCharacter.method or "Instant",
        Callback = function(value) NexusState.upgradeCharacter.method = value end
    })

    local function checkResources(option1, option2)
        local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))
        if not userData then return false, "Player data not found" end
        local resources = {
            Cash = { path = userData:FindFirstChild("Cash"), needed = 5000000000 },
            Level = { path = userData:FindFirstChild("Level") and userData.Level:FindFirstChild("Level"), needed = 500 },
            Crystal = { path = userData:FindFirstChild("Crystal"), needed = 1000 },
            Ticket = { path = userData:FindFirstChild("Ticket"), needed = 200 }
        }
        local function getValue(res)
            if res and res.path then
                if typeof(res.path) == "Instance" and typeof(res.path) == "Instance" and res.path:IsA("NumberValue") or res.path:IsA("IntValue") then
                    return res.path.Value
                end
            end
            return 0
        end
        local need1 = resources[option1]
        local need2 = resources[option2]
        if not need1 or not need2 then return false, "Invalid option" end
        local val1 = getValue(need1)
        local val2 = getValue(need2)
        if val1 >= need1.needed and val2 >= need2.needed then
            return true, "Enough"
        else
            local msg = option1 .. " (" .. val1 .. "/" .. need1.needed .. ") or " .. option2 .. " (" .. val2 .. "/" .. need2.needed .. ")"
            return false, "Not enough: " .. msg
        end
    end

    local autoToggle = Cfg.register(UpgradeSection:CreateToggle(Cfg.wrap("Toggle", "Auto Rebirth", {
        Name = "Auto Rebirth",
        Default = false,
        Callback = function(value)
            NexusState.autoRebirthRunning = value
            if value then
                if NexusState.autoRebirthThread then
                    task.cancel(NexusState.autoRebirthThread)
                    NexusState.autoRebirthThread = nil
                end
                NexusState.autoRebirthThread = task.spawn(function()
                    while NexusState.autoRebirthRunning do
                        pcall(function()
                            if #NexusState.selectedOptions ~= 2 then
                                NexusLib:Notify({ Title = "Auto Rebirth", Message = "Please select exactly 2 options!", Duration = 2 })
                                task.wait(2)
                                return
                            end
                            local ok, msg = checkResources(NexusState.selectedOptions[1], NexusState.selectedOptions[2])
                            if ok then
                                NexusState.upgradeCharacter.teleported = false
                                NexusState.upgradeCharacter.oldPosition = nil
                                if NexusState.upgradeCharacter.method == "]=],[=[
Teleport" then
                                    local npc = Workspace:FindFirstChild("NPC")
                                    if npc then
                                        local func = npc:FindFirstChild("Function")
                                        if func then
                                            local theShadow = func:FindFirstChild("The Shadow")
                                            if typeof(theShadow) == "Instance" and theShadow:IsA("Model") then
                                                local hrp = theShadow:FindFirstChild("HumanoidRootPart")
                                                if hrp then
                                                    local char = LocalPlayer.Character
                                                    if char then
                                                        local root = char:FindFirstChild("HumanoidRootPart")
                                                        if root then
                                                            NexusState.upgradeCharacter.oldPosition = root.Position
                                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))
                                                            NexusState.upgradeCharacter.teleported = true
                                                            task.wait(0.3)
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                    if not NexusState.upgradeCharacter.teleported then
                                        NexusLib:Notify({ Title = "Auto Rebirth", Message = "Could not find The Shadow, teleport failed. Continuing anyway.", Duration = 3 })
                                    end
                                end

                                local result = NexusState.UpgradeCharacter:InvokeServer(NexusState.selectedOptions)
                                if result and result.ok then
                                    NexusLib:Notify({ Title = "Auto Rebirth", Message = "Upgraded successfully!", Duration = 2 })
                                else
                                    NexusLib:Notify({ Title = "Auto Rebirth", Message = "Upgrade failed: " .. (result and result.msg or "unknown error"), Duration = 3 })
                                end

                                if NexusState.upgradeCharacter.teleported and NexusState.upgradeCharacter.oldPosition then
                                    local char = LocalPlayer.Character
                                    if char then
                                        local root = char:FindFirstChild("HumanoidRootPart")
                                        if root then
                                            root.CFrame = CFrame.new(NexusState.upgradeCharacter.oldPosition)
                                            NexusState.upgradeCharacter.oldPosition = nil
                                            NexusState.upgradeCharacter.teleported = false
                                        end
                                    end
                                end
                            else
                                if math.random(1, 5) == 1 then
                                    NexusLib:Notify({ Title = "Auto Rebirth", Message = msg, Duration = 3 })
                                end
                            end
                        end)
                        task.wait(2)
                    end
                end)
            else
                if NexusState.autoRebirthThread then
                    task.cancel(NexusState.autoRebirthThread)
                    NexusState.autoRebirthThread = nil
                end
                if NexusState.upgradeCharacter.teleported and NexusState.upgradeCharacter.oldPosition then
                    local char = LocalPlayer.Character
                    if char then
                        local root = char:FindFirstChild("HumanoidRootPart")
                        if root then
                            root.CFrame = CFrame.new(NexusState.upgradeCharacter.oldPosition)
                            NexusState.upgradeCharacter.oldPosition = nil
                            NexusState.upgradeCharacter.teleported = false
                        end
                    end
                end
                NexusLib:Notify({ Title = "Auto Rebirth", Message = "Stopped", Duration = 2 })
            end
        end
    })), "Toggle", "Auto Rebirth", {
        Name = "Auto Rebirth",
        Default = false,
        Callback = function(value)
            NexusState.autoRebirthRunning = value
            if value then
                if NexusState.autoRebirthThread then
                    task.cancel(NexusState.autoRebirthThread)
                    NexusState.autoRebirthThread = nil
                end
                NexusState.autoRebirthThread = task.spawn(function()
                    while NexusState.autoRebirthRunning do
                        pcall(function()
                            if #NexusState.selectedOptions ~= 2 then
                                NexusLib:Notify({ Title = "Auto Rebirth", Message = "Please select exactly 2 options!", Duration = 2 })
                                task.wait(2)
                                return
                            end
                            local ok, msg = checkResources(NexusState.selectedOptions[1], NexusState.selectedOptions[2])
                            if ok then
                                NexusState.upgradeCharacter.teleported = false
                                NexusState.upgradeCharacter.oldPosition = nil
                                if NexusState.upgradeCharacter.method == "Teleport" then
                                    local npc = Workspace:FindFirstChild("NPC")
                                    if npc then
                                        local func = npc:FindFirstChild("Function")
                                        if func then
                                            local theShadow = func:FindFirstChild("The Shadow")
                                            if typeof(theShadow) == "Instance" and theShadow:IsA("Model") then
                                                local hrp = theShadow:FindFirstChild("HumanoidRootPart")
                                                if hrp then
                                                    local char = LocalPlayer.Character
                                                    if char then
                                                        local root = char:FindFirstChild("HumanoidRootPart")
                                                        if root then
                                                            NexusState.upgradeCharacter.oldPosition = root.Position
                                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))
                                                            NexusState.upgradeCharacter.teleported = true
                                                            task.wait(0.3)
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                    if not NexusState.upgradeCharacter.teleported then
                                        NexusLib:Notify({ Title = "Auto Rebirth", Message = "Could not find The Shadow, teleport failed. Continuing anyway.", Duration = 3 })
                                    end
                                end

                                local result = NexusState.UpgradeCharacter:InvokeServer(NexusState.selectedOptions)
                                if result and result.ok then
                                    NexusLib:Notify({ Title = "Auto Rebirth", Message = "Upgraded successfully!", Duration = 2 })
                                else
                                    NexusLib:Notify({ Title = "Auto Rebirth", Message = "Upgrade failed: " .. (result and result.msg or "unknown error"), Duration = 3 })
                                end

                                if NexusState.upgradeCharacter.teleported and NexusState.upgradeCharacter.oldPosition then
                                    local char = LocalPlayer.Character
                                    if char then
                                        local root = char:FindFirstChild("HumanoidRootPart")
                                        if root then
                                            root.CFrame = CFrame.new(NexusState.upgradeCharacter.oldPosition)
                                            NexusState.upgradeCharacter.oldPosition = nil
                                            NexusState.upgradeCharacter.teleported = false
                                        end
                                    end
                                end
                            else
                                if math.random(1, 5) == 1 then
                                    NexusLib:Notify({ Title = "Auto Rebirth", Message = msg, Duration = 3 })
                                end
                            end
                        end)
                        task.wait(2)
                    end
                end)
            else
                if NexusState.autoRebirthThread then
                    task.cancel(NexusState.autoRebirthThread)
                    NexusState.autoRebirthThread = nil
                end
                if NexusState.upgradeCharacter.teleported and NexusState.upgradeCharacter.oldPosition then
                    local char = LocalPlayer.Character
                    if char then
                        local root = char:FindFirstChild("HumanoidRootPart")
                        if root then
                            root.CFrame = CFrame.new(NexusState.upgradeCharacter.oldPosition)
                            NexusState.upgradeCharacter.oldPosition = nil
                            NexusState.upgradeCharacter.teleported = false
                        end
                    end
                end
                NexusLib:Notify({ Title = "Auto Rebirth", Message = "Stopped", Duration = 2 })
            end
        end
    })

    local function displayStats()
        local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))
        if not userData then return end
        local cash = userData:FindFirstChild("Cash") and userData.Cash.Value or 0
        local level = userData:FindFirstChild("Level") and userData.Level:FindFirstChild("Level") and userData.Level.Level.Value or 0
        local crystal = userData:FindFirstChild("Crystal") and userData.Crystal.Value or 0
        local ticket = userData:FindFirstChild("Ticket") and userData.Ticket.Value or 0
        NexusLib:Notify({
            Title = "Resources",
            Message = string.format("Cash: %.2fB | Level: %d | Crystal: %d | Ticket: %d", cash/1e9, level, crystal, ticket),
            Duration = 4
        })
    end
    UpgradeSection:CreateButton({ Name = "Check Resources", Callback = displayStats })
end

