-- ===== TELEPORT TAB =====
-- ============================================================
do
    local TeleportTab = Window:CreateTab("Tele]=],[=[
port")
    local TPSection = TeleportTab:CreateSection("NPC & Weather", "Left")

    TPSection:CreateButton({
        Name = "TP to Taoist",
        Callback = function()
            local taoist = nil
            for _, v in pairs(Workspace:GetDescendants()) do
                if typeof(v) == "Instance" and typeof(v) == "Instance" and v:IsA("Model") and string.find(v.Name:lower(), "taoist") and v:FindFirstChild("HumanoidRootPart") then
                    taoist = v
                    break
                end
            end
            if taoist and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
                LocalPlayer.Character.HumanoidRootPart.CFrame = taoist.HumanoidRootPart.CFrame * CFrame.new(0, 0, 4)
                NexusLib:Notify({ Title = "Taoist", Message = "Teleported!", Duration = 3 })
            else
                NexusLib:Notify({ Title = "Taoist", Message = "Not found!", Duration = 3 })
            end
        end
    })

    TPSection:CreateButton({
        Name = "TP to Maoshan",
        Callback = function()
            local maoshan = nil
            for _, v in pairs(Workspace:GetDescendants()) do
                if typeof(v) == "Instance" and typeof(v) == "Instance" and v:IsA("Model") and (string.find(v.Name:lower(), "maoshan") or string.find(v.Name:lower(), "merchant")) and v:FindFirstChild("HumanoidRootPart") then
                    maoshan = v
                    break
                end
            end
            if maoshan and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
                LocalPlayer.Character.HumanoidRootPart.CFrame = maoshan.HumanoidRootPart.CFrame * CFrame.new(0, 0, 4)
                NexusLib:Notify({ Title = "Maoshan", Message = "Teleported!", Duration = 3 })
            else
                NexusLib:Notify({ Title = "Maoshan", Message = "Not found!", Duration = 3 })
            end
        end
    })

    TPSection:CreateButton({
        Name = "TP to Spirit",
        Callback = function()
            local godFolder = Workspace:FindFirstChild("NPC") and Workspace.NPC:FindFirstChild("God")
            if not godFolder then
                NexusLib:Notify({ Title = "Spirit", Message = "Folder God not found!", Duration = 3 })
                return
            end
            local target = nil
            for _, child in pairs(godFolder:GetChildren()) do
                if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("Model") then
                    local hrp = child:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        target = hrp
                        break
                    end
                elseif typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("BasePart") then
                    target = child
                    break
                end
            end
            if not target then
                NexusLib:Notify({ Title = "Spirit", Message = "No Spirit found!", Duration = 3 })
                return
            end
            local char = LocalPlayer.Character
            if not char then return end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if hrp then
                hrp.CFrame = target.CFrame + Vector3.new(0, 3, 0)
                NexusLib:Notify({ Title = "Spirit", Message = "Teleported to Spirit!", Duration = 3 })
            end
        end
    })

    -- ===== NPC TELEPORT + GIVE FISH (Duan Gan / Dumb guy) =====
    do
        local GiveSection = TeleportTab:CreateSection("Quest NPC & Give Fish", "Right")

        local function npcRoot()
            return Workspace:FindFirstChild("NPC")
        end

        local function findNpcHrp(npcName)
            local hrp = nil
            pcall(function()
                local npcFolder = npcRoot()
                if not npcFolder then return end
                local f = npcFolder:FindFirstChild("Function")
                local m = (f and f:FindFirstChild(npcName)) or npcFolder:FindFirstChild(npcName)
                if m then hrp = m:FindFirstChild("HumanoidRootPart") or m:FindFirstChild("Torso") end
            end)
            return hrp
        end

        local function teleportNearNpc(npcName, offset)
            local hrp = findNpcHrp(npcName)
            local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            if not hrp or not root then return false end
            pcall(function()
                root.CFrame = CFrame.new(hrp.Position + (offset or Vector3.new(0, 3, 0)))
            end)
            return true
        end

        local function parseWeightKg(text)
            local clean = string.gsub(text, "[,%s]", "")
            local num, suffix = string.match(clean, "(%d+%.?%d*)([KkMmBbTt]?)")
            local n = tonumber(num) or 0
            if suffix == "K" or suffix == "k" then
                n = n * 1000
            elseif suffix == "M" or suffix == "m" then
                n = n * 1000000
            elseif suffix == "B" or suffix == "b" then
                n = n * 1000000000
            elseif suffix == "T" or suffix == "t" then
                n = n * 1000000000000
            end
            return n
        end

        local function getFishKg(item)
            local w = 0
            pcall(function()
                local attr = item:GetAttribute("Weight")
                if tonumber(attr) and tonumber(attr) > 0 then
                    w = tonumber(attr)
                elseif typeof(item) == "Instance" and typeof(item) == "Instance" and item:IsA("StringValue") then
                    local parts = {}
                    for part in string.gmatch(item.Value, "[^|]+") do table.insert(parts, part) end
                    if #parts >= 2 then w = parseWeightKg(parts[2]) end
                elseif typeof(item) == "Instance" and typeof(item) == "Instance" and item:IsA("NumberValue") or item:IsA("IntValue") then
                    w = tonumber(item.Value) or 0
                end
            end)
            return w
        end

        local function collectBigFish(minKg)
            local out = {}
            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))
            local inv = userData and userData:FindFirstChild("Inventory")
            if not inv then return out end
            for _, item in pairs(inv:GetChildren()) do
                local kg = getFishKg(item)
                if kg >= minKg then
                    table.insert(out, { item = item, name = item.Name, kg = kg })
                end
            end
            table.sort(out, function(a, b) return a.kg > b.kg end)
            return out
        end

        local function giveFishToDumbGuy(entry)
            if not entry or not entry.item then return false end
            local model = nil
            pcall(function()
                local npcFolder = npcRoot()
                local f = npcFolder and npcFolder:FindFirstChild("Function")
                model = f and f:FindFirstChild("Dumb guy")
            end)
            if not model then return false end
            local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            local origCF = root and root.CFrame
            if teleportNearNpc("Dumb guy", Vector3.new(0, 3, 0)) then task.wait(0.4) end

            pcall(function() Events.StartDialogue:FireServer("Dumb guy", model) end)
            task.wait(0.15)

            local fired = false
            pcall(function()
                Events.ChooseDialogueOption:FireServer("Dumb guy", 1, "GiveFish", { model })
                fired = true
            end)

            if origCF and root and root.Parent then
                task.wait(0.3)
                pcall(function() root.CFrame = origCF end)
            end
            return fired
        end
        GiveSection:CreateButton({
            Name = "Teleport To Duan Gan NPC",
            Callback = function()
                if teleportNearNpc("Duan Gan", Vector3.new(0, 3, 0)) then
                    NexusLib:Notify({ Title = "Duan Gan", Message = "Teleported!", Duration = 3 })
                else
                    NexusLib:Notify({ Title = "Duan Gan", Message = "NPC not found!", Duration = 3 })
                end
            end
        })

        GiveSection:CreateButton({
            Name = "Teleport To Dumb Guy NPC",
            Callback = function()
                if teleportNearNpc("Dumb guy", Vector3.new(0, 3, 0)) then
                    NexusLib:Notify({ Title = "Dumb Guy", Message = "Teleported!", Duration = 3 })
                else
                    NexusLib:Notify({ Title = "Dumb Guy", Message = "NPC not found!", Duration = 3 })
                end
            end
        })

        GiveSection:CreateButton({
            Name = "Give 1 Fish > 2M kg",
            Callback = function()
                local list = collectBigFish(2000000)
                if #list == 0 then
                    NexusLib:Notify({ Title = "Give Fish", Message = "No fish over 2M kg in inventory!", Duration = 3 })
                    return
                end
                local e = list[1]
                if giveFishToDumbGuy(e) then
                    NexusLib:Notify({ Title = "Give Fish", Message = "Gave " .. e.name .. " (" .. tostring(e.kg) .. " kg)", Duration = 3 })
                else
                    NexusLib:Notify({ Title = "Give Fish", Message = "Failed to give fish!", Duration = 3 })
                end
            end
        })

        NexusState.autoGiveFishRunning = false
        NexusState.autoGiveFishThread = nil

        Cfg.register(GiveSection:CreateToggle(Cfg.wrap("Toggle", "Auto Give Fish > 2M kg", {
            Name = "Auto Give Fish > 2M kg",
            Default = false,
            Callback = function(value)
                NexusState.autoGiveFishRunning = value
                if NexusState.autoGiveFishThread then
                    pcall(task.cancel, NexusState.autoGiveFishThread)
                    NexusState.autoGiveFishThread = nil
                end
                if not value then return end
                NexusState.autoGiveFishThread = task.spawn(function()
                    while NexusState.autoGiveFishRunning do
                        pcall(function()
                            local list = collectBigFish(2000000)
                            if #list > 0 then giveFishToDumbGuy(list[1]) end
                        end)
                        task.wait(2)
                    end
                end)
            end
        })), "Toggle", "Auto Give Fish > 2M kg", {
            Name = "Auto Give Fish > 2M kg",
            Default = false,
            Callback = function(value)
                NexusState.autoGiveFishRunning = value
                if NexusState.autoGiveFishThread then
                    pcall(task.cancel, NexusState.autoGiveFishThread)
                    NexusState.autoGiveFishThread = nil
                end
                if not value then return end
                NexusState.autoGiveFishThread = task.spawn(function()
                    while NexusState.autoGiveFishRunning do
                        pcall(function()
                            local list = collectBigFish(2000000)
                            if #list > 0 then giveFishToDumbGuy(list[1]) end
                        end)
                        task.wait(2)
                    end
                end)
            end
        })

        -- ===== AUTO FARM CA 2M+ KG =====
        NexusState.autoFarm2MRunning = false
        NexusState.autoFarm2MThread = nil

       ]=],[=[
 local function findBigKgIsland()
            local best, bestKg = nil, 0
            pcall(function()
                local rarity = Info:FindFirstChild("FishingAreaRarity")
                if not rarity then return end
                for _, area in pairs(rarity:GetChildren()) do
                    local maxKg = area:FindFirstChild("MaxKg")
                    local v = maxKg and tonumber(maxKg.Value) or 0
                    if v >= 2000000 and v > bestKg then
                        bestKg = v
                        best = area.Name
                    end
                end
            end)
            return best, bestKg
        end

        Cfg.register(GiveSection:CreateToggle(Cfg.wrap("Toggle", "Auto Farm 2M+ kg Fish", {
