-- ============================================================
-- ===== DEFINE _G.codetorun AND _G.codes =====
-- ============================================================

_G.codetorun = [[
    -- Use the globals assigned by the main script
    local RunService = _G.RunService
    local LocalPlayer = _G.LocalPlayer
    local UserInputService = _G.UserInputService
    local VirtualUser = _G.VirtualUser
    local Events = _G.Events
    local MiscFlags = _G.MiscFlags
    local alive = _G.alive
    local runtimeEnv = _G.runtimeEnv

    local noclipAccum = 0
    if runtimeEnv.NexusNoclipConn then pcall(function() runtimeEnv.NexusNoclipConn:Disconnect() end) end
    runtimeEnv.NexusNoclipConn = RunService.Stepped:Connect(function(_, dt)
        if not alive() then return end
        if not MiscFlags.Noclip then return end
        noclipAccum = noclipAccum + (dt or 0.016)
        if noclipAccum < 0.4 then return end
        noclipAccum = 0
        local char = LocalPlayer.Character
        if char then
            for _, v in ipairs(char:GetDescendants()) do
                if typeof(v) == "Instance" and v:IsA("BasePart") and v.CanCollide then v.CanCollide = false end
            end
        end
    end)

    UserInputService.JumpRequest:Connect(function()
        if MiscFlags.InfiniteJump and LocalPlayer.Character then
            local h = LocalPlayer.Character:FindFirstChildOfClass('Humanoid')
            if h then h:ChangeState(Enum.HumanoidStateType.Jumping) end
        end
    end)

    local function nudgeInput()
        if _G.Fishing and _G.Fishing.Flags and not _G.Fishing.Flags.AntiAFK then return end
        local _nm = false
        pcall(function()
            local _c = LocalPlayer.Character
            local _h = _c and _c:FindFirstChildOfClass("Humanoid")
            local _md = _h and _h.MoveDirection
            if _md and (math.abs(_md.X or 0) + math.abs(_md.Z or 0) > 0.05) then _nm = true end
        end)
