local nexusPanel = LocalPlayer.PlayerGui:FindFirstChild("NexusPanel")

local function DisableNexusKeyboardActivation(object)
    if typeof(object) == "Instance" and object:IsA("GuiObject") then
        object.Selectable = false
    end
end

