task.spawn(function()
    while true do
        local waitTime = 0.5 + math.random(0, 30) / 100
        task.wait(waitTime)
        if not alive() then break end
        if Fishing.Flags.MainFarm and (Fishing.Flags.AutoCast or Fishing.Flags.AutoSkill or Fishing.Flags.AntiAFK) then
            if Fishing.Flags.AutoCast then
                local c = LocalPlayer.Character
                if c then
                    -- Fix freeze: khong force cast khi player dang di chuyen
                    local moving = false
                    pcall(function()
                        local hum = c:FindFirstChildOfClass("Humanoid")
                        if hum and hum.MoveDirection then
                            local md = hum.MoveDirection
                            moving = math.abs(md.X or 0) + math.abs(md.Z or 0) > 0.05
                        end
                    end)
                    if (not c:GetAttribute("Fishing")) and not moving and NexusState.canCastNow() then
                        pcall(function() Events.Fishing:FireServer() end)
                    elseif NexusState.isDoingUseBaitQuest and MainGui:FindFirstChild("Fishing") and MainGui.Fishing.Visible then
                        pcall(function()
                            local root = c:FindFirstChild("HumanoidRootPart")
                            Events.Fishing:FireServer(root and root.CFrame or nil)
                        end)
                    end
                end
            end
            if Fishing.Flags.AutoSkill and MainGui:FindFirstChild("Fishing") and MainGui.Fishing.Visible then
                pcall(function()
                    local char = LocalPlayer.Character
                    local skillsFolder = char and char:FindFirstChild("Skills")
                    if skillsFolder then
                        local readySkills = {}
                        fo]=],[=[
r _, skill in ipairs(skillsFolder:GetChildren()) do
                            if typeof(skill) == "Instance" and skill:IsA("NumberValue") and skill.Value <= 0 then
                                local key = skill:GetAttribute("Key")
                                if key then readySkills[key] = true end
                            end
                        end

                        if Fishing.Flags.SkillMode == "Sequential" then
                            local now = tick()
                            local delay = Fishing.Flags.SkillDelay or 0.3
                            if now - (NexusState.lastSkillCastTime or 0) >= delay then
                                local seqStr = Fishing.Flags.SkillSequence or "Z,X,C,V"
                                local seq = {}
                                for k in string.gmatch(seqStr:upper(), "[ZXCV]") do
                                    table.insert(seq, k)
                                end
                                if #seq == 0 then seq = {"Z", "X", "C", "V"} end

                                local attempts = 0
                                while attempts < #seq do
                                    attempts = attempts + 1
                                    if not NexusState.skillSeqIndex or NexusState.skillSeqIndex > #seq then
                                        NexusState.skillSeqIndex = 1
                                    end
                                    local targetKey = seq[NexusState.skillSeqIndex]
                                    NexusState.skillSeqIndex = NexusState.skillSeqIndex + 1
                                    if readySkills[targetKey] then
                                        Events.UseSkill:FireServer(targetKey)
                                        NexusState.lastSkillCastTime = now
                                        break
                                    end
                                end
                            end
                        else
                            local selectedSkills = Fishing.Flags.SelectedSkills or {"Z", "X", "C", "V"}
                            for _, key in ipairs(selectedSkills) do
                                if readySkills[key] then
                                    Events.UseSkill:FireServer(key)
                                end
                            end
                        end
                    end
                end)
            else
                NexusState.skillSeqIndex = 1
            end
            if Fishing.Flags.AntiAFK and tick() - (NexusState.lastAfkFire or 0) > 60 then
                local _afkMoving = false
                pcall(function()
                    local _c = LocalPlayer.Character
                    local _h = _c and _c:FindFirstChildOfClass("Humanoid")
                    local _md = _h and _h.MoveDirection
                    if _md and (math.abs(_md.X or 0) + math.abs(_md.Z or 0) > 0.05) then _afkMoving = true end
                end)
                if not _afkMoving then
                    NexusState.lastAfkFire = tick()
                    pcall(function() Events.AFK:FireServer() end)
                end
            end
        end
    end
end)

