-- GUI click QTE (Rewritten Auto Enzo)
local prevBarPos = 0
local lastFrameTime = tick()
local currentSpeed = 0
local lastQTEClick = 0
local lastQTEHitboxX = nil

-- Click QTE the same way the game listens: desktop Fishing GUI button
-- first (Fishing2.MouseButton1Down path), then mobile button, then
-- synthetic mouse input as last fallback. Never fires blind.
local EnzoQTEGui = nil
local function findEnzoQTEGui()
    if EnzoQTEGui and EnzoQTEGui.Parent then return EnzoQTEGui end
    EnzoQTEGui = nil
    local fishing = MainGui:FindFirstChild("Fishing")
    local btn = fishing and (fishing:FindFirstChild("Fishing2") or fishing:FindFirstChild("Button"))
    if btn and typeof(btn) == "Instance" and btn:IsA("GuiButton") then EnzoQTEGui = btn return btn end
    local mobileFishing = MainGui:FindFirstChild("Mobile") and MainGui.Mobile:FindFirstChild("Fishing")
    local mbtn = mobileFishing and (mobileFishing:FindFirstChild("Button") or mobileFishing)
    if mbtn and typeof(mbtn) == "Instance" and mbtn:IsA("GuiButton") then EnzoQTEGui = mbtn return mbtn end
    if fishing and typeof(fishing) == "Instance" and fishing:IsA("GuiButton") then EnzoQTEGui = fishing return fishing end
    return nil
end

local function pressEnzoQTE()
    local btn = findEnzoQTEGui()
    if btn and firesignal then
        pcall(firesignal, btn.MouseButton1Down)
        return
    end
    pcall(function()
        local vim = game:GetService("VirtualInputManager")
        vim:SendMouseButtonEvent(0, 0, 0, true, game, 0)
        vim:SendMouseButtonEvent(0, 0, 0, false, game, 0)
    end)
end

local renderAccum = 0
local RENDER_THROTTLE = 0.033
local cachedFishingGui = nil
local cachedBossBar = nil

local function updateFrameLogic(dt)
    if not cachedFishingGui or not cachedFishingGui.Parent then
        cachedFishingGui = MainGui and MainGui:FindFirstChild("Fishing")
        cachedBossBar = cachedFishingGui and cachedFishingGui:FindFirstChild("BossFightBar")
    end
    local fishing = cachedFishingGui
    local bossBar = cachedBossBar
    local bossBarVisible = bossBar ~= nil and bossBar.Visible == true
    local fishingVisible = fishing ~= nil and fishing.Visible == true

    if not bossBarVisible then
        renderAccum = renderAccum + dt
        if renderAccum < RENDER_THROTTLE then return end
        renderAccum = 0
    end

    if (Fishing.Flags.AnchorLock or Fishing.Flags.AutoSkillCheck or Fishing.Flags.AutoLongDiaohai) and fishingVisible then
        if Fishing.Flags.AnchorLock and not bossBarVisible and not Fishing.BossFarm.PendingCancel then
            local bf = fishing:FindFirstChild("BarFrame")
            local b = bf and bf:FindFirstChild("Bar")
            if b then b.Position = UDim2.new(0.5, 0, 0.5, 0) end
        end

        if (Fishing.Flags.AutoSkillCheck or Fishing.Flags.AutoLongDiaohai) and bossBarVisible then
            local bar = bossBar:FindFirstChild("Bar")
            local hitbox = bossBar:FindFirstChild("Hitbox")
            local badHitbox = bossBar:FindFirstChild("HitboxBad")
            if bar and hitbox and hitbox.Visible then
                local barPos = bar.Position.X.Scale
                local hbPos = hitbox.Position.X.Scale - hitbox.Size.X.Scale * hitbox.AnchorPoint.X
                local hbSize = hitbox.Size.X.Scale
                if lastQTEHitboxX ~= hbPos then
                    lastQTEHitboxX = hbPos
                    lastQTEClick = 0
                end

                local now = tick()
                local dtFrame = now - lastFrameTime
                lastFrameTime = now

                if dtFrame > 0.001 and dtFrame < 0.1 then
                    local rawSpeed = (barPos - prevBarPos) / dtFrame
                    prevBarPos = barPos
                    if math.abs(rawSpeed) < 5 then
                        currentSpeed = currentSpeed * 0.7 + rawSpeed * 0.3
                    end
                else
                    prevBarPos = barPos
                end

                local lastInput = UserInputService:GetLastInputType()
                local latency = (lastInput == Enum.UserInputType.Touch) and 0.06 or 0.025
                local compensatedBarPos = barPos - (currentSpeed * latency)

                local margin = hbSize * 0.15
                local badOverlap = false
                if badHitbox and badHitbox.Visible then
                    local badLeft = badHitbox.Position.X.Scale - badHitbox.Size.X.Scale * badHitbox.AnchorPoint.X
                    badOverlap = compensatedBarPos >= badLeft and compensatedBarPos <= badLeft + badHitbox.Size.X.Scale
                end

                if not badOverlap and compensatedBarPos >= hbPos + margin and compensatedBarPos <= hbPos + hbSize - margin then
                    if tick() - lastQTEClick > 0.15 then
                        lastQTEClick = tick()
                        pressEnzoQTE()
                    end
                end
            else
                lastQTEHitboxX = nil
                prevBarPos = 0
                lastFrameTime = tick()
                currentSpeed = 0
            end
        else
            lastQTEHitboxX = nil
            prevBarPos = 0
            lastFrameTime = tick()
            currentSpeed = 0
        end
    end

    if NexusState.flying and NexusState.bg and NexusState.bv and LocalPlayer.Character then
        local h = LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        local hum = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
        if h and hum then
            local cameraLook = Camera.CFrame.LookVector
            local move = hum.MoveDirection
            local horizontal = Vector3.new(move.X, 0, move.Z)
            local vertical = (NexusState.flyKeys.Up and 1 or 0) - (NexusState.flyKeys.Down and 1 or 0)
            NexusState.bv.Velocity = horizontal * NexusState.flySpeed + Vector3.new(0, vertical * NexusState.flySpeed, 0)
            local look = Vector3.new(cameraLook.X, 0, cameraLook.Z)
            if look.Magnitude > 0.01 then
                NexusState.bg.CFrame = CFrame.lookAt(h.Position, h.Position + look.Unit)
            end
        end
    end

    if MiscFlags.FullBright then
        if not NexusState.fullBrightApplied then
            Lighting.Ambient = Color3.new(1,1,1)
            Lighting.ColorShift_Bottom = Color3.new(1,1,1)
            Lighting.ColorShift_T]=],[=[
op = Color3.new(1,1,1)
            Lighting.Brightness = 2
            Lighting.OutdoorAmbient = Color3.new(1,1,1)
            NexusState.fullBrightApplied = true
        end
    else
        if NexusState.fullBrightApplied then
            NexusState.fullBrightApplied = false
        end
    end
end

runtimeEnv.NexusFrameConnection = RunService.RenderStepped:Connect(function(dt)
    if not alive() then return end
    pcall(updateFrameLogic, dt)
end)

