    local function isHooked(f)
        if type(f) ~= "function" then return false end
        if ishooked and ishooked(f) then return true end
        return false
    end
    if isHooked(_raw_loadstring) or (loadstring and isHooked(loadstring)) then
        LP:Kick("Nexus Security: loadstring tampering detected.")
        while true do task.wait(9999) end
        return
    end

    local GUARD = {
        API_URL = "https://vgvaxescpirfdkrcamyk.supabase.co/functions/v1/key-system",
        PROTOCOL_VERSION = 3,
        -- Freemium chi doc file FREEMIUM (khong doc file premium de tranh de lan)
        KEY_FILES = { "NexusFreemiumKey.txt" },
        TIMEOUT = 20,
        RETRY = 2,
        -- Doi thanh true neu muon: khong tim thay key thi VAN CHAY (che do offline).
        OFFLINE_FALLBACK = true,
    }

    local function getHWID()
        local candidates = {
            function() return gethwid and gethwid() end,
            function() return game:GetService("RbxAnalyticsService"):GetClientId() end,
        }
        for _, getter in ipairs(candidates) do
            local ok, value = pcall(getter)
            if ok and type(value) == "string" and #value >= 8 then
                return value .. ":" .. tostring(LP.UserId)
            end
        end
        return string.format("player:%d:place:%d", LP.UserId, game.PlaceId)
    end

    local _raw_req = (syn and syn.request) or http_request or request or (fluxus and fluxus.request)
    local function requestAdapter()
        return _raw_req or (syn and syn.request) or http_request or request or (fluxus and fluxus.request)
    end

    local function api(action, fields)
        local payload = fields or {}
        payload.action = action
        payload.protocol_version = GUARD.PROTOCOL_VERSION
        payload.hwid = getHWID()
        local lastErr = "NETWORK_ERROR"
        for _ = 1, GUARD.RETRY do
            local ok, result = pcall(function()
                local requestFn = requestAdapter()
                local encoded = HttpService:JSONEncode(payload)
                if requestFn then
                    local raw = requestFn({
                        Url = GUARD.API_URL, Method = "POST",
                        Headers = { ["Content-Type"] = "application/json" },
                        Body = encode]=],[=[
d, Timeout = GUARD.TIMEOUT,
                    })
                    return HttpService:JSONDecode(raw.Body or raw.body or "{}")
                end
                return nil -- khong co http adapter
            end)
            if ok and type(result) == "table" then return result end
            task.wait(1)
        end
        return { ok = false, code = lastErr }
    end

    -- Doc key: uu tien getgenv().Key, sau do quet tat ca ten file ho tro
    -- FIX: nguong 12 ky tu la doan mo -> key ngan hon 12 bi coi nhu KHONG CO
    -- roi bi deny oan. Chi can khong rong; dung/sai de server phan xu.
    local function trim(s)
        return (tostring(s):gsub("^%s+", ""):gsub("%s+$", ""))
    end
    local function readKey()
        if type(_rt.Key) == "string" then
            local k = trim(_rt.Key)
            if #k >= 4 then return k end
        end
        local found
        for _, fname in ipairs(GUARD.KEY_FILES) do
            pcall(function()
                if not found and isfile and readfile and isfile(fname) then
                    local s = readfile(fname)
                    if type(s) == "string" and #trim(s) >= 4 then found = trim(s) end
                end
            end)
            if found then break end
        end
        return found
    end

    local function notify(msg)
        -- 1) print luon hoat dong tren moi executor
        pcall(function() print("[Nexus Hub] " .. tostring(msg)) end)
        -- 2) NexusLib neu co (khong dung notify Roblox)
        pcall(function()
            local slib = _rt.NexusLib
            if slib and slib.Notify then slib:Notify({ Title = "Nexus Hub", Message = msg, Duration = 6 }) end
        end)
    end

    local function deny(reason)
        notify(reason)
        pcall(function()
            if _rt.NexusReport then
                _rt.NexusReport("Nexus: Thong bao key", tostring(reason) ..
                    "\n\nExecute source truc tiep da bi KHOA. Phai dung loader hwfnew de vao.")
            end
        end)
        LP:Kick("Nexus: " .. tostring(reason))
    end

    -- ================== BẢO VỆ TOKEN HANDOFF CHỐNG BYPASS ==================
    -- Chống trò bypass gõ: getgenv().NexusPremiumVerified = true
    -- Bắt buộc phải có Server Nonce hợp lệ từ Loader vừa gửi sang và tiêu thụ ngay (One-time token).
    local serverNonce = _rt.NexusGuardNonce
    _rt.NexusGuardNonce = nil -- Tiêu thụ ngay lập tức token dùng 1 lần

    local isValidHandoff = false
    if type(serverNonce) == "string" and #serverNonce >= 8 then
        -- Có server token từ loader gửi qua -> hợp lệ
        isValidHandoff = true
    elseif (_rt.NexusPremiumVerified == true or _rt.NexusFreemiumVerified == true) and type(_rt.Key) == "string" and #_rt.Key >= 6 then
        -- Fallback trường hợp loader cũ nhưng phải kèm theo Key hợp lệ trong session
        isValidHandoff = true
    end

    -- Xóa toàn bộ cờ runtime để không bị tái sử dụng
    _rt.NexusPremiumVerified = nil
    _rt.NexusFreemiumVerified = nil
    _rt.NexusMainLoaded = nil
    _rt.NexusVerifiedTier = nil

    if not isValidHandoff then
        -- Execute source trực tiếp hoặc cố tình set cờ giả mạo -> KICK ngay
        local reason = "Bao mat: Khong the thuc thi source truc tiep. Phai qua loader chinh thuc!"
        notify(reason)
        pcall(function()
            if _rt.NexusReport then
                _rt.NexusReport("Nexus Security", reason)
            end
        end)
        LP:Kick("Nexus: " .. reason)
        while true do task.wait(9999) end
        return
    end

    _rt.NexusFreemiumVerified = true
end
-- ===== END ANTI-BYPASS GUARD =====

