do
    pcall(function()
        LocalPlayer:SetAttribute("NexusUser", true)
        if LocalPlayer.Character then
            LocalPlayer.Character:SetAttribute("NexusUser", true)
        end
        LocalPlayer.CharacterAdded:Connect(function(char)
            pcall(function()
                LocalPlayer:SetAttribute("NexusUser", true)
                char:SetAttribute("NexusUser", true)
            end)
        end)
    end)

    pcall(function()
        if hookmetamethod and not _G.NexusNamecallHooked then
            _G.NexusNamecallHooked = true
            local oldNamecall
            oldNamecall = hookmetamethod(game, "__namecall", function(self, ...)
                local method = getnamecallmethod()
                if (method == "ReportAbuse" or method == "reportAbuse") and self == Players then
                    local args = {...}
                    local target = args[1]
                    local isNexusUser = false
                    if typeof and typeof(target) == "Instance" then
                        if typeof(target) == "Instance" and typeof(target) == "Instance" and target:IsA("Player") then
                            if target:GetAttribute("NexusUser") or (target.Character and target.Character:GetAttribute("NexusUser")) then
                                isNexusUser = true
                            end
                        end
                    elseif type(target) == "string" then
                        local p = Players:FindFirstChild(target)
                        if p and (p:GetAttribute("NexusUser") or (p.Character and p.Character:GetAttribute("NexusUser"))) then
                            isNexusUser = true
                        end
                    end
                    if isNexusUser and NexusState.antiReportEnabled ~= false then
                        NexusLib:Notify({
                            Title = "Nexus Shield",
                            Message = "You cannot report another Nexus Hub user!",
                            Duration = 3
                        })
                        return nil
                    end
                end
                return oldNamecall(self, ...)
            end)
        end
    end)
end

