    do
        local PraySection = FarmingTab:CreateSection("Auto Pray Spirit")
        local prayEnabled = false
        local prayThread = nil
        local prayConnections = {}
        local lastInteractTime = 0
        local cooldown = 2 -- seconds between interactions

        -- Scan and handle spirits
        local function scanAndPray()
            local godFolder = workspace:FindFirstChild("NPC") and workspace.NPC:FindFirstChild("God")
            if not godFolder then return end

            local now = tick()
            if now - lastInteractTime < cooldown then return end

            -- Find every model in the God folder (sub-models included)
            local models = {}
            for _, child in ipairs(godFolder:GetDescendants()) do
                if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("Model") then
                    table.insert(models, child)
                end
            end

            for _, model in ipairs(models) d]=],[=[
o
                -- Find HumanoidRootPart or PrimaryPart
                local hrp = model:FindFirstChild("HumanoidRootPart")
                if not hrp then
                    hrp = model.PrimaryPart
                end
                if hrp then
                -- Find Talk and ProximityPrompt
                local talk = hrp:FindFirstChild("Talk")
                if talk then
                local prompt = talk:FindFirstChild("ProximityPrompt")
                if prompt then
                -- Configure ProximityPrompt
                pcall(function()
                    prompt.RequiresLineOfSight = false
                    prompt.HoldDuration = 0
                end)

                -- Teleport to the spirit position
                local char = LocalPlayer.Character
                if char then
                    local root = char:FindFirstChild("HumanoidRootPart")
                    if root then
                        root.CFrame = hrp.CFrame + Vector3.new(0, 2, 0)
                    end
                end

                -- Trigger ProximityPrompt
                local success = false
                -- Cach 1: Fire Proximity Prompt
                if fireproximityprompt and prompt then
                    pcall(function()
                        fireproximityprompt(prompt)
                        success = true
                    end)
                end
                -- Method 2: firesignal
                if firesignal and prompt then
                    pcall(function()
                        firesignal(prompt.PromptButtonHoldBegan)
                        task.wait(0.1)
                        firesignal(prompt.PromptButtonHoldEnded)
                        success = true
                    end)
                end
                -- Method 2: use VirtualInputManager to press E
                if not success then
                    pcall(function()
                        local vim = game:GetService("VirtualInputManager")
                        if vim then
                            vim:SendKeyEvent(true, Enum.KeyCode.E, false, game)
                            task.wait(0.1)
                            vim:SendKeyEvent(false, Enum.KeyCode.E, false, game)
                            success = true
                        end
                    end)
                end
                -- Method 3: use VirtualUser (last fallback)
                if not success then
                    pcall(function()
                        if VirtualUser then
                            VirtualUser:Button2Down(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)
                            task.wait(0.1)
                            VirtualUser:Button2Up(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)
                            success = true
                        end
                    end)
                end

                if success then
                    lastInteractTime = now
                    NexusLib:Notify({ Title = "Pray", Message = "Prayed to " .. model.Name, Duration = 2 })
                    break -- only interact with one spirit per pass
                end
                end
                end
                end
            end
        end

        -- Start helper
        local function startPray()
            if prayEnabled then return end
            prayEnabled = true
            prayThread = task.spawn(function()
                while prayEnabled do
                    pcall(scanAndPray)
                    task.wait(1.5) -- scan every 1.5 seconds
                end
            end)
            NexusLib:Notify({ Title = "Auto Pray", Message = "Enabled", Duration = 2 })
        end

        local function stopPray()
            prayEnabled = false
            if prayThread then
                task.cancel(prayThread)
                prayThread = nil
            end
            for _, conn in ipairs(prayConnections) do
                pcall(function() conn:Disconnect() end)
            end
            prayConnections = {}
            NexusLib:Notify({ Title = "Auto Pray", Message = "Disabled", Duration = 2 })
        end

        -- Toggle
        Cfg.register(PraySection:CreateToggle(Cfg.wrap("Toggle", "Auto Teleport + Interact (Pray) Spirit", {
            Name = "Auto Teleport + Interact (Pray) Spirit",
            Default = false,
            Callback = function(value)
                if value then
                    startPray()
                else
                    stopPray()
                end
            end
        })), "Toggle", "Auto Teleport + Interact (Pray) Spirit", {
            Name = "Auto Teleport + Interact (Pray) Spirit",
            Default = false,
            Callback = function(value)
                if value then
                    startPray()
                else
                    stopPray()
                end
            end
        })
    end

end

