        })

        local ignoreLockedToggle = Cfg.register(TraitSection:CreateToggle(Cfg.wrap("Toggle", "Ignore Locked", {
            Name = "Ignore Locked",
            Default = false,
            Callback = function(value) ignoreLocked = value end
        })), "Toggle", "Ignore Locked", {
            Name = "Ignore Locked",
            Default = false,
            Callback = function(value) ignoreLocked = value end
        })

        local rerollMethodDropdown = Cfg.register(TraitSection:CreateDropdown(Cfg.wrap("Dropdown", "Reroll Method", {
