        })

        local RerollTrait = Events:FindFirstChild("RerollTrait")

        TraitSection:CreateButton({
            Name = "Reroll Until Trait",
            Callback = function()
                if NexusState.Reroll.running then
                    NexusState.Reroll.running = false
                    if NexusState.Reroll.thread then
                        task.cancel(NexusState.Reroll.thread)
                        NexusState.Reroll.thread = nil
                    end
                    if NexusState.Reroll.teleported and NexusState.Reroll.oldPosition then
                        local char = LocalPlayer.Character
                        if char then
                            local root = char:FindFirstChild("HumanoidRootPart")
                            if root then
                                root.CFrame = CFrame.new(NexusState.Reroll.oldPosition)
                                NexusState.Reroll.oldPosition = nil
                                NexusState.Reroll.teleported = false
                            end
                        end
                    end
                    NexusLib:Notify({ Title = "Reroll", Message = "Stopped", Duration = 2 })
                    return
                end

                local skillName = selectedSkillForReroll
            ]=],[=[
    local targetTrait = selectedTargetTrait
                if not skillName or skillName == "" or skillName == "No skill owned" then
                    NexusLib:Notify({ Title = "Reroll", Message = "Select a valid skill", Duration = 2 })
                    return
                end
                if not targetTrait or targetTrait == "" or targetTrait == "No trait available" then
                    NexusLib:Notify({ Title = "Reroll", Message = "Select a target trait", Duration = 2 })
                    return
                end
                if not RerollTrait then
                    NexusLib:Notify({ Title = "Reroll", Message = "RerollTrait event not found", Duration = 2 })
                    return
                end
                local p = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))
                local rerollCount = p and p:FindFirstChild("Trait Reroll")
                if rerollCount and rerollCount.Value <= 0 then
                    NexusLib:Notify({ Title = "Reroll", Message = "No rerolls left!", Duration = 2 })
                    return
                end

                NexusState.Reroll.teleported = false
                NexusState.Reroll.oldPosition = nil
                if NexusState.Reroll.method == "Teleport" then
                    local npc = Workspace:FindFirstChild("NPC")
                    if npc then
                        local func = npc:FindFirstChild("Function")
                        if func then
                            local nanjiang = func:FindFirstChild("Nanjiang")
                            if typeof(nanjiang) == "Instance" and nanjiang:IsA("Model") then
                                local hrp = nanjiang:FindFirstChild("HumanoidRootPart")
                                if hrp then
                                    local char = LocalPlayer.Character
                                    if char then
                                        local root = char:FindFirstChild("HumanoidRootPart")
                                        if root then
                                            NexusState.Reroll.oldPosition = root.Position
                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))
                                            NexusState.Reroll.teleported = true
                                            task.wait(0.3)
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if not NexusState.Reroll.teleported then
                        NexusLib:Notify({ Title = "Reroll", Message = "Could not find Nanjiang, teleport failed. Continuing anyway.", Duration = 3 })
                    end
                end

                NexusState.Reroll.running = true
                NexusLib:Notify({ Title = "Reroll", Message = "Reroll started... Target: " .. targetTrait, Duration = 2 })

                NexusState.Reroll.thread = task.spawn(function()
                    local successCount = 0
                    while NexusState.Reroll.running do
                        local p2 = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))
                        local count = p2 and p2:FindFirstChild("Trait Reroll")
                        if count and count.Value <= 0 then
                            NexusLib:Notify({ Title = "Reroll", Message = "No rerolls left, stopping", Duration = 2 })
                            break
                        end
                        local success, result = pcall(function()
                            return RerollTrait:InvokeServer(skillName, ignoreLocked)
                        end)
                        if not success or not result then
                            NexusLib:Notify({ Title = "Reroll", Message = "Reroll failed, stopping", Duration = 2 })
                            break
                        end
                        successCount = successCount + 1
                        local traitName = result.Name
                        if traitName == targetTrait then
                            NexusLib:Notify({ Title = "Reroll", Message = "Got " .. targetTrait .. " on " .. skillName .. " after " .. successCount .. " rerolls!", Duration = 3 })
                            break
                        end
                        task.wait(0.15)
                    end

                    if NexusState.Reroll.teleported and NexusState.Reroll.oldPosition then
                        local char = LocalPlayer.Character
                        if char then
                            local root = char:FindFirstChild("HumanoidRootPart")
                            if root then
                                root.CFrame = CFrame.new(NexusState.Reroll.oldPosition)
                                NexusState.Reroll.oldPosition = nil
                                NexusState.Reroll.teleported = false
                            end
                        end
                    end
                    NexusState.Reroll.running = false
                    NexusState.Reroll.thread = nil
                    NexusLib:Notify({ Title = "Reroll", Message = "Stopped", Duration = 2 })
                end)
            end
        })
    end

