-- ===== EXCHANGE TAB =====
-- ============================================================
do
    local ExchangeTab = Window:CreateTab("Exchange")
    local ExchangeSection = ExchangeTab:CreateSection("Exchange Items")

    local exchangeAmount = 1
    local exchangeType = "Trait Reroll"

    Cfg.register(ExchangeSection:CreateTextbox(Cfg.wrap("Textbox", "Quantity", {
        Name = "Quantity",
        Placeholder = "1",
        Default = "1",
        Callback = function(value)
            local num = tonumber(value)
            if num and num >= 1 then
                exchangeAmount = math.floor(num)
            else
                exchangeAmount = 1
            end
        end
    })), "Textbox", "Quantity", {
        Name = "Quantity",
        Placeholder = "1",
        Default = "1",
        Callback = function(value)
            local num = tonumber(value)
            if num and num >= 1 then
                exchangeAmount = math.floor(num)
            else
                exchangeAmount = 1
            end
        end
    })

    Cfg.register(ExchangeSection:CreateDropdown(Cfg.wrap("Dropdown", "Choose an item", {
        Name = "Choose an item",
        Options = {"Trait Reroll", "EssenceOrb"},
        Default = "Trait Reroll",
        Callback = function(value) exchangeType = value end
    })), "Dropdown", "Choose an item", {
        Name = "Choose an item",
        Options = {"Trait Reroll", "EssenceOrb"},
        Default = "Trait Reroll",
        Callback = function(value) exchangeType = value end
    })

    local exchangeMethodDropdown = Cfg.register(ExchangeSection:CreateDropdown(Cfg.wrap("Dropdown", "Exchange Method", {
        Name = "Exchange Method",
        Options = {"Instant", "Teleport"},
        Default = NexusState.exchange.method or "Instant",
        Callback = function(value) NexusState.exchange.method = value end
    })), "Dropdown", "Exchange Method", {
        Name = "Exchange Method",
        Options = {"Instant", "Teleport"},
        Default = NexusState.exchange.method or "Instant",
        Callback = function(value) NexusState.exchange.method = value end
    })

    ExchangeSection:CreateButton({
        Name = "Exchange now",
        Callback = function()
            local userId = LocalPlayer.UserId
            local userData = Data:FindFirstChild(tostring(userId))
            if not userData then
                NexusLib:Notify({ Title = "Exchange", Message = "Player data not found!", Duration = 2 })
                return
            end
            local crystal = userData:FindFirstChild("Crystal")
            local cash = userData:FindFirstChild("Cash")
            if not crystal or not cash then
                NexusLib:Notify({ Title = "Exchange", Message = "Crystal or Cash not found!", Duration = 2 })
                return
            end
            local qty = exchangeAmount
            local crystalNeed = qty * 5
            local cashNeed = qty * 5000000
            if crystal.Value < crystalNeed then
                NexusLib:Notify({ Title = "Exchange", Message = "Not enough Crystals! Need " .. crystalNeed .. ", have " .. crystal.Value, Duration = 3 })
                return
            end
            if cash.Value < cashNeed then
                NexusLib:Notify({ Title = "Exchange", Message = "Not enough Cash! Need " .. cashNeed .. ", have " .. cash.Value, Duration = 3 })
                return
            end

            NexusState.exchange.teleported = false
            NexusState.exchange.oldPosition = nil
            if NexusState.exchange.method == "Teleport" then
                local npc = Workspace:FindFirstChild("NPC")
                if npc then
                    local func = npc:FindFirstChild("Function")
                    if func then
                        local nanjiang = func:FindFirstChild("Nanjiang")
                        if typeof(nanjiang) == "Instance" and nanjiang:IsA("Model") then
                            local hrp = nanjiang:FindFirstChild("HumanoidRootPart")
                            if hrp then
                                local char = LocalPlayer.Character
                                if char then
                                    local root = char:FindFirstChild("HumanoidRootPart")
                                    if root then
                                        NexusState.exchange.oldPosition = root.Position
                                        root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))
                                        NexusState.exchange.teleported = true
                                        task.wait(0.3)
                                    end
                                end
                            end
                        end
                    end
                end
                if not NexusState.exchange.teleported then
                    NexusLib:Notify({ Title = "Exchange", Message = "Could not find Nanjiang, teleport failed. Continuing anyway.", Duration = 3 })
                end
            end

            local success, err = pcall(function()
                Events.Exchange:FireServer(exchangeType, qty)
            end)

            if NexusState.exchange.teleported and NexusState.exchange.oldPosition then
                task.wait(0.2)
                local char = LocalPlayer.Character
                if char then
                    local root = char:FindFirstChild("HumanoidRootPart")
                    if root then
                        root.CFrame = CFrame.new(NexusState.exchange.oldPosition)
                        NexusState.exchange.oldPosition = nil
                        NexusState.exchange.teleported = false
                    end
                end
            end

            if success then
                NexusLib:Notify({ Title = "Exchange", Message = "Exchanged " .. qty .. " " .. exchangeType .. "!", Duration = 2 })
            else
                NexusLib:Notify({ Title = "Exchange", Message = "Exchange failed: " .. tostring(err), Duration = 2 })
            end
        end
    })
end

