do
    local QuestsTab = Window:CreateTab("Quests")

    -- Teleport to Ticket Quest Giver, open dialogue, fire action, go back.
    -- StartDialogue first: server ignores ChooseDialogueOption with no open dialogue.
    NexusState.ticketLastFire = NexusState.ticketLastFire or 0
    NexusState.ticketFailCount = NexusState.ticketFailCount or 0
    local function ticketGoFire(action)
        if _G and _G.Events then
            local sd = _G.Events:FindFirstChild("StartDialogue")
            local cd = _G.Events:FindFirstChild("ChooseDialogueOption")
            if not sd or not cd then return false end
        end
        local giver = nil
        pcall(function()
            local npc = Workspace:FindFirstChild("NPC")
            local npcFunc = npc and npc:FindFirstChild("Function")
            giver = npcFunc and npcFunc:FindFirstChild("Ticket Quest Giver")
        end)
        if not giver then return false end
        local extraData = { giver }
        local charNow = LocalPlayer.Character
        local root = charNow and charNow:FindFirstChild("HumanoidRootPart")
        local giverPos = nil
        pcall(function()
            if typeof(giver) == "Instance" and typeof(giver) == "Instance" and giver:IsA("Model") then
                local hrp = giver:FindFirstChild("HumanoidRootPart")
                if hrp then
                    giverPos = hrp.Position
                elseif giver.PrimaryPart then
                    giverPos = giver.PrimaryPart.Position
                else
                    giverPos = giver:GetPivot().Position
                end
            elseif typeof(giver) == "Instance" and typeof(giver) == "Instance" and giver:IsA("BasePart") then
                giverPos = giver.Position
            end
        end)
        local origCF = root and root.CFrame
        if root and giverPos then
            pcall(function() root.CFrame = CFrame.new(giverPos + Vector3.new(0, 3, 0)) end)
            task.wait(0.45)
        end
        pcall(function()
            Events.StartDialogue:FireServer("Ticket Quest Giver", giver)
        end)
        task.wait(0.25)
        pcall(function()
            Events.ChooseDialogueOption:FireServer("Ticket Quest Giver", 1, action, extraData)
        end)
        task.wait(0.2)
        if origCF and root and root.Parent then
            pcall(function() root.CFrame = origCF end)
        end
        return true
    end

    -- ===== AUTO CLAIM TICKET QUEST =====
    do
        local ClaimSection = QuestsTab:CreateSection("Auto Claim Ticket Quest")
        local questTypes = {"Easy Quest", "Hard Quest"}
        local selectedQuest = questTypes[1]

        local function HasActiveQuest()
            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))
            if not userData then return false end
            local quest = userData:FindFirstChild("Quest")
            if not quest then return false end
            local main = quest:FindFirstChild("Main")
            if not main then return false end
            for _, child in pairs(main:GetChildren()) do
                if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("Folder") then
                    local name = child.Name
                    if name == "Easy Ticket Quest" or name == "Hard Ticket Quest" then
                        return true
                    end
                end
            end
            return false
        end

        local claimDropdown = Cfg.register(ClaimSection:CreateDropdown(Cfg.wrap("Dropdown", "Select Quest Type", {
            Name = "Select Quest Type",
            Options = questTypes,
            Default = selectedQuest,
            Callback = function(value) selectedQuest = value end
        })), "Dropdown", "Select Quest Type", {
            Name = "Select Quest Type",
            Options = questTypes,
            Default = selectedQuest,
            Callback = function(value) selectedQuest = value end
        })

        local autoClaimToggle = Cfg.register(ClaimSection:CreateToggle(Cfg.wrap("Toggle", "Auto Claim Ticket Quest (Fast)", {
            Name = "Auto Claim Ticket Quest (Fast)",
            Default = false,
            Callback = function(value)
                NexusState.autoClaimRunning = value
                if value then
                    if NexusState.autoClaimThread then
                        task.cancel(NexusState.autoClaimThread)
                        NexusState.autoClaimThread = nil
                    end
                    NexusState.autoClaimThread = task.spawn(function()
                        while NexusState.autoClaimRunning do
                            pcall(function()
                                if not HasActiveQuest() then
                                    if tick() - (NexusState.ticketLastFire or 0) < 3 ]=],[=[
then return end
                                    NexusState.ticketLastFire = tick()
                                    local selAction = nil
                                    if selectedQuest == "Easy Quest" then
                                        selAction = "EasyAcceptQuest"
                                    else
                                        selAction = "HardAcceptQuest"
                                    end
                                    if ticketGoFire(selAction) and HasActiveQuest() then
                                        NexusState.ticketFailCount = 0
                                        NexusLib:Notify({
                                            Title = "Quest",
                                            Message = "Claimed " .. selectedQuest,
                                            Duration = 2
                                        })
                                    else
                                        NexusState.ticketFailCount = (NexusState.ticketFailCount or 0) + 1
                                        if NexusState.ticketFailCount == 5 then
                                            NexusLib:Notify({ Title = "Quest", Message = "Claim failed 5 times. Check NPC or quest type.", Duration = 4 })
                                        end
                                    end
                                else
                                    NexusState.ticketFailCount = 0
                                end
                            end)
                            task.wait(0.5)
                        end
                    end)
                else
                    if NexusState.autoClaimThread then
                        task.cancel(NexusState.autoClaimThread)
                        NexusState.autoClaimThread = nil
                    end
                    NexusState.ticketFailCount = 0
                    NexusLib:Notify({ Title = "Quest", Message = "Auto claim stopped", Duration = 2 })
                end
            end
        })), "Toggle", "Auto Claim Ticket Quest (Fast)", {
            Name = "Auto Claim Ticket Quest (Fast)",
            Default = false,
            Callback = function(value)
                NexusState.autoClaimRunning = value
                if value then
                    if NexusState.autoClaimThread then
                        task.cancel(NexusState.autoClaimThread)
                        NexusState.autoClaimThread = nil
                    end
                    NexusState.autoClaimThread = task.spawn(function()
                        while NexusState.autoClaimRunning do
                            pcall(function()
                                if not HasActiveQuest() then
                                    if tick() - (NexusState.ticketLastFire or 0) < 3 then return end
                                    NexusState.ticketLastFire = tick()
                                    local selAction = nil
                                    if selectedQuest == "Easy Quest" then
                                        selAction = "EasyAcceptQuest"
                                    else
                                        selAction = "HardAcceptQuest"
                                    end
                                    if ticketGoFire(selAction) and HasActiveQuest() then
                                        NexusState.ticketFailCount = 0
                                        NexusLib:Notify({
                                            Title = "Quest",
                                            Message = "Claimed " .. selectedQuest,
                                            Duration = 2
                                        })
                                    else
                                        NexusState.ticketFailCount = (NexusState.ticketFailCount or 0) + 1
                                        if NexusState.ticketFailCount == 5 then
                                            NexusLib:Notify({ Title = "Quest", Message = "Claim failed 5 times. Check NPC or quest type.", Duration = 4 })
                                        end
                                    end
                                else
                                    NexusState.ticketFailCount = 0
                                end
                            end)
                            task.wait(0.5)
                        end
                    end)
                else
                    if NexusState.autoClaimThread then
                        task.cancel(NexusState.autoClaimThread)
                        NexusState.autoClaimThread = nil
                    end
                    NexusState.ticketFailCount = 0
                    NexusLib:Notify({ Title = "Quest", Message = "Auto claim stopped", Duration = 2 })
                end
            end
        })
    end

    -- ===== AUTO DO TICKET QUEST =====
    local DoSection = QuestsTab:CreateSection("Auto Do Ticket Quest")
    -- Store the dynamic controls
    local islandModeDropdown = nil
    local islandDropdown = nil
    local islandDropdownFrame = nil
    local selectedIslandMode = "Auto Select Island"
    local selectedIslandName = "Island 1"
    local islandList = {"Island 1", "Island 2", "Island 3", "Island 4", "Island 5",
                        "Island 6", "Island 7", "Island 8", "Island 9", "Island 10", "Island 11", "Island 12", "Island 13"}

    -- Remove the island dropdown (if present)
    local function clearIslandDropdown()
        if islandDropdownFrame and islandDropdownFrame._frame then
            pcall(function()
                if type(islandDropdownFrame.Destroy) == "function" then
                    islandDropdownFrame:Destroy()
                elseif islandDropdownFrame._frame and type(islandDropdownFrame._frame.Destroy) == "function" then
                    islandDropdownFrame._frame:Destroy()
                end
            end)
        end
        islandDropdownFrame = nil
        islandDropdown = nil
    end

    -- Create the island dropdown
    -- NOTE: picking an island forces manual mode, so Auto Do Ticket
    -- never pulls the player back to the recommended island.
    local function createIslandDropdown()
        clearIslandDropdown()
        islandDropdown = Cfg.register(DoSection:CreateDropdown(Cfg.wrap("Dropdown", "Choose an island", {
            Name = "Choose an island",
            Options = islandList,
            Default = selectedIslandName,
            Callback = function(value)
                selectedIslandName = value
                selectedIslandMode = "Choose Island Manual"
                pcall(function() if modeDropdown and modeDropdown.Set then modeDropdown:Set("Choose Island Manual") end end)
            end
        })), "Dropdown", "Choose an island", {
            Name = "Choose an island",
            Options = islandList,
            Default = selectedIslandName,
            Callback = function(value)
                selectedIslandName = value
                selectedIslandMode = "Choose Island Manual"
                pcall(function() if modeDropdown and modeDropdown.Set then modeDropdown:Set("Choose Island Manual") end end)
            end
        })
        islandDropdownFrame = islandDropdown
    end

    -- Create the mode dropdown
    local modeDropdown = Cfg.register(DoSection:CreateDropdown(Cfg.wrap("Dropdown", "Island Selection Mode", {
        Name = "Island Selection Mode",
        Options = {"Auto Select Island", "Choose Island Manual"},
        Default = "Auto Select Island",
        Callback = function(value)
            selectedIslandMode = value
            if value == "Choose Island Manual" then
                createIslandDropdown()
            else
                clearIslandDropdown()
            end
        end
    })), "Dropdown", "Island Selection Mode", {
        Name = "Island Selection Mode",
        Options = {"Auto Select Island", "Choose Island Manual"},
        Default = "Auto Select Island",
        Callback = function(value)
            selectedIslandMode = value
            if value == "Choose Island Manual" then
                createIslandDropdown()
            else
                clearIslandDropdown()
            end
        end
    })

    -- Create the default island dropdown (hidden, shown only in manual mode)
    -- Not built up front, only once manual is picked

    -- ===== Target island resolver =====
    local function getTargetIsland()
        if selectedIslandMode == "Auto Select Island" then
            return getRecommendedIsland()
        else
            for _, island in ipairs(NexusState.islands) do
                if island.name == selectedIslandName then
                    return island
                end
            end
            return nil
        end
    end


    local function parseQuestString(str)
        if not str or str == "" then return nil, nil end
        local parts = {}
        for part in string.gmatch(str, "[^,]+") do table.insert(parts, part) end
        if #parts >= 3 then
            local target = nil
            local typ = nil
            if string.find(parts[1], "Boss") then
                target = tonumber(parts[3])
                typ = parts[1]
            else
                target = tonumber(parts[2])
                typ = parts[3]
            end
            if target and typ then return target, typ end
        end
        return nil, nil
    end

    local function getCurrentQuestProgress()
        local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))
        if not userData then return nil end
        local quest = userData:FindFirstChild("Quest")
        if not quest then return nil end
        local main = quest:FindFirstChild("Main")
        if not main then return nil end
        for _, folder in pairs(main:GetChildren()) do
            if typeof(folder) == "Instance" and typeof(folder) == "Instance" and folder:IsA("Folder") and (folder.Name == "Easy Ticket Quest" or folder.Name == "Hard Ticket Quest") then
                local current = nil
                local target = nil
                local typ = nil
                local questName = folder.Name
                for _, child in pairs(folder:GetChildren()) do
                    if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("NumberValue") or child:IsA("IntValue") then
                        if child.Name == "1" then
                            current = child.Value
                        end
                    end
                end
                local objective = folder:FindFirstChild("Objective")
                if objective then
                    for _, child in pairs(objective:GetChildren()) do
                        if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("StringValue") and child.Name == "1" then
                            local val = child.Value
                            if val and val ~= "" then
                                NexusState.ticketObjectiveText = tostring(val)
                                local t, ty = parseQuestString(val)
                                if t and ty then
                                    target = t
                                    typ = ty
                                end
                            end
                        end
                    end
                end
                if current and target and typ then
                    return current, target, questName, typ
                end
            end
        end
        return nil
    end

    local function updateQuestStatus()
        local current, target, questName, typ = getCurrentQuestProgress()
        ]=],[=[
if current and target and questName then
            NexusState.ticketTargetCount = target
            NexusState.ticketCurrentCount = current
            NexusState.ticketQuestActive = true
            if current >= target then
                if not NexusState.ticketQuestClaimed then
                    NexusLib:Notify({ Title = "Quest", Message = "Complete! Claiming reward...", Duration = 2 })
                    -- TP to NPC, turn in with retries, chain next quest right away.
                    local turnedIn = false
                    for _ = 1, 5 do
                        if ticketGoFire("Quest") then
                            for _ = 1, 6 do
                                task.wait(0.15)
                                if not getCurrentQuestProgress() then
                                    turnedIn = true
                                    break
                                end
                            end
                        end
                        if turnedIn then break end
                        task.wait(0.2)
                    end
                    if turnedIn then
                        NexusState.ticketQuestClaimed = true
                        NexusState.ticketLastFire = 0
                        NexusState.ticketFailCount = 0
                        NexusState.isDoingUseBaitQuest = false
                        disableAllFishing()
                        NexusState.ticketQuestActive = false
                        NexusLib:Notify({ Title = "Quest", Message = "Turned in. Claim toggle takes next quest.", Duration = 3 })
                    else
                        NexusLib:Notify({ Title = "Quest", Message = "Turn-in failed, retrying...", Duration = 2 })
                    end
                end
                NexusState.isDoingUseBaitQuest = false
                Fishing.Flags.AutoSkill = false
                Fishing.Flags.AutoSkillCheck = false
                NexusState.ticketQuestActive = false
                return
            end
            NexusState.ticketQuestClaimed = false

            -- Teleport to target island (manual choice wins)
            local targetIsland = getTargetIsland()
            if targetIsland then
                local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                if hrp then
                    local targetPos = targetIsland.cframe.Position + Vector3.new(0, 5, 0)
                    if (hrp.Position - targetPos).Magnitude > 25 and (tick() - (NexusState.ticketLastTele or 0) > 3) then
                        NexusState.ticketLastTele = tick()
                        safeTeleport(hrp, CFrame.new(targetPos))
                    end
                end
            end

                        local need = string.lower(tostring(typ or "") .. " " .. tostring(NexusState.ticketObjectiveText or ""))
            local function needHas(...)
                for _, k in ipairs({...}) do
                    if string.find(need, k, 1, true) then return true end
                end
                return false
            end
            NexusState.isDoingUseBaitQuest = false
            -- Ticket pool: use bait / catch fish / heavy fish (1.5M) / use skill.
            -- No boss quests here, so boss words inside fish names must not trigger boss farm.
            if needHas("usebait", "use bait", "bait") then
                NexusState.isDoingUseBaitQuest = true
                enableBasicFishing()
                Fishing.Flags.AutoFarmBoss = false
                Fishing.Flags.AutoFarmSecretBoss = false
                Fishing.Flags.AnchorLock = true
                Fishing.Flags.AutoSkill = true
                Fishing.Flags.AutoSkillCheck = true
                MiscFlags.AutoBuy = true
                local buyable = GetBuyableBaits()
                local found = false
                for _, name in ipairs(buyable) do
                    if name == "Basic Bait" then
                        NexusState.selectedBait = name
                        found = true
                        break
                    end
                end
                if not found then
                    NexusState.selectedBait = buyable[1] or "No bait available"
                end
                MiscFlags.AutoEquipBait = true
            elseif needHas("skill") then
                enableBasicFishing()
                Fishing.Flags.AutoFarmBoss = false
                Fishing.Flags.AutoFarmSecretBoss = false
                Fishing.Flags.AutoSkill = true
                Fishing.Flags.AutoSkillCheck = true
                Fishing.Flags.AnchorLock = true
            elseif needHas("weight", "kg", "heavy", "1.5m", "1,5m", "1500000") then
                enableBasicFishing()
                Fishing.Flags.AutoFarmBoss = false
                Fishing.Flags.AutoFarmSecretBoss = false
                pcall(function() Events.UpdateFishProgression:FireServer() end)
            elseif needHas("fish", "catch", "fishing") then
                enableBasicFishing()
                Fishing.Flags.AutoFarmBoss = false
                Fishing.Flags.AutoFarmSecretBoss = false
                pcall(function() Events.UpdateFishProgression:FireServer() end)
            else
                enableBasicFishing()
                Fishing.Flags.AutoFarmBoss = false
                Fishing.Flags.AutoFarmSecretBoss = false
            end
        else
            if NexusState.ticketQuestActive then
                NexusState.ticketQuestActive = false
                NexusState.ticketTargetCount = 0
                NexusState.ticketCurrentCount = 0
                NexusState.isDoingUseBaitQuest = false
                Fishing.Flags.AutoSkill = false
                Fishing.Flags.AutoSkillCheck = false
                disableAllFishing()
            end
            NexusState.isDoingUseBaitQuest = false
            NexusState.ticketQuestClaimed = false
            NexusState.ticketLastFire = 0
            NexusState.ticketFailCount = 0
            NexusState.ticketObjectiveText = nil
        end
    end

    local function startAutoDoLoop()
        if NexusState.autoDoThread then return end
        NexusState.autoDoThread = task.spawn(function()
            while NexusState.autoDoRunning do
                pcall(updateQuestStatus)
                task.wait(1)
            end
            NexusState.autoDoThread = nil
        end)
    end

    local autoDoToggle = Cfg.register(DoSection:CreateToggle(Cfg.wrap("Toggle", "Auto Do Ticket Quest (Fast)", {
        Name = "Auto Do Ticket Quest (Fast)",
        Default = false,
        Callback = function(value)
            NexusState.autoDoRunning = value
            if value then
                if NexusState.autoDoThread then
                    task.cancel(NexusState.autoDoThread)
                    NexusState.autoDoThread = nil
                end
                startAutoDoLoop()
                NexusLib:Notify({ Title = "Auto Do Quest", Message = "Started monitoring quest objective", Duration = 2 })
            else
                if NexusState.autoDoThread then
                    task.cancel(NexusState.autoDoThread)
