    do
        local DailySection = QuestsTab:CreateSection("Daily Quests")
        local dailyRunning = false
        local dailyThread = nil

        local function teleportToIsland(island)
            if not island then return false end
            local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            if not hrp then return false end
            local target = island.cframe.Position + Vector3.new(0, 5, 0)
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
            hrp.CFrame = CFrame.new(target)
            return true
        end

        local function doDailyQuest()
            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))
            if not userData then
                NexusLib:Notify({ Title = "Daily Quest", Message = "User data not found!", Duration = 2 })
                return
            end
            local dailyFolder = userData:FindFirstChild("Quest") and userData.Quest:FindFirstChild("Daily")
            if not dailyFolder then
                NexusLib:Notify({ Title = "Daily Quest", Message = "Daily quest folder not found!", Duration = 2 })
                return
            end
            local questFolders = {}
            for _, child in pairs(dailyFolder:GetChildren()) do
                if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("Folder") then
                    table.insert(questFolders, child)
                end
            end
            if #questFolders == 0 then
                NexusLib:Notify({ Title = "Daily Quest", Message = "No daily quests available!", Duration = 2 })
                return
            end
            local selectedFolder = questFolders[math.random(1, #questFolders)]
            local questId = selectedFolder.Name
            local progression = selectedFolder:FindFirstChild("Progression")
            local questType = selectedFolder:FindFirstChild("QuestType")
            if not progression or not questType then
                NexusLib:Notify({ Title = "Daily Quest", Message = "Missing Progression or QuestType in quest " .. questId, Duration = 2 })
                return
            end
            local currentProgress = (typeof(progression) == "Instance" and progression:IsA("NumberValue")) and progression.Value or 0
            local qType = (typeof(questType) == "Instance" and questType:IsA("StringValue")) and questType.Value or ""

            NexusLib:Notify({
                Title = "Daily Quest",
                Message = "Selected quest " .. questId .. " | Type: " .. qType .. " | Progress: " .. currentProgress,
                Duration = 4
            })

            if qType == "PlayTime" then
                NexusLib:Notify({ Title = "Daily Quest", Message = "PlayTime quest: just play for 30 minutes!", Duration = 3 })
                return
            end

            if qType == "Fishing" then
                local island = getRecommendedIsland()
                if not island then
            ]=],[=[
