    -- ===== SPECTATE PLAYER =====
        local spectateEnabled = false
        local spectateTarget = nil
        local oldSubject = nil
        local oldCameraType = nil
        local espConnections = {}
        
        -- Start spectate
        local function startSpectate()
            if spectateEnabled then return end
            
            -- Find the first player other than yourself
            local targetPlayer = nil
            for _, player in ipairs(Players:GetPlayers()) do
                if player ~= LocalPlayer then
                    targetPlayer = player
                    break
                end
            end
            
            if not targetPlayer then
                NexusLib:Notify({ Title = "Spectate", Message = "No other players to spectate!", Duration = 2 })
                if NexusState.spectateToggle then
                    NexusState.spectateToggle:Set(false)
                end
                return
            end
            
            -- Check whether the target has a character
            if not targetPlayer.Character then
                NexusLib:Notify({ Title = "Spectate", Message = targetPlayer.Name .. " has no character!", Duration = 2 })
                if NexusState.spectateToggle then
                    NexusState.spectateToggle:Set(false)
                end
                return
            end
            
            local targetHrp = targetPlayer.Character:FindFirstChild("HumanoidRootPart")
            if not targetHrp then
                NexusLib:Notify({ Title = "Spectate", Message = "Cannot find HumanoidRootPart of " .. targetPlayer.Name, Duration = 2 })
                if NexusState.spectateToggle then
                    NexusState.spectateToggle:Set(false)
                end
                return
            end
            
            spectateEnabled = true
            spectateTarget = targetPlayer
            
            local camera = workspace.CurrentCamera
            oldSubject = camera.CameraSubject
            oldCameraType = camera.CameraType
            
            -- Lock the camera onto the target
            camera.CameraSubject = targetHrp
            camera.CameraType = Enum.CameraType.Custom
            
            NexusLib:Notify({ Title = "Spectate", Message = "Spectating " .. targetPlayer.Name, Duration = 2 })
        end
        
        -- Stop spectate
        local function stopSpectate()
            spectateEnabled = false
            spectateTarget = nil
            
            -- Reset the camera back to the local player
            pcall(function()
                local camera = workspace.CurrentCamera
                if oldSubject then
                    camera.CameraSubject = oldSubject
                    oldSubject = nil
                end
                if oldCameraType then
                    camera.CameraType = oldCameraType
                    oldCameraType = nil
                end
            end)
            
            NexusLib:Notify({ Title = "Spectate", Message = "Stopped spectating", Duration = 2 })
        end
        
        -- Toggle Spectate Player
        local spectateToggle = Cfg.register(PlayerSection:CreateToggle(Cfg.wrap("Toggle", "Spectate Player", {
            Name = "Spectate Player",
            Default = false,
            Callback = function(value)
                if value then
                    startSpectate()
                else
                    stopSpectate()
                end
            end
        })), "Toggle", "Spectate Player", {
            Name = "Spectate Player",
            Default = false,
            Callback = function(value)
                if value then
                    startSpectate()
                else
                    stopSpectate()
                end
            end
        })
        
        -- Persist the toggle in NexusState
        NexusState.spectateToggle = spectateToggle
        
        -- Handle the target leaving or their character resetting
        local function onTargetCharacterAdded()
            if spectateEnabled and spectateTarget then
                local char = spectateTarget.Character
                if char then
                    local hrp = char:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        workspace.CurrentCamera.CameraSubject = hrp
                    end
                end
            end
        end
        
        -- Listen for the target's character changing
        local charAddedConn = nil
        local playerRemovingConn = Players.PlayerRemoving:Connect(function(player)
            if spectateEnabled and player == spectateTarget then
                stopSpectate()
                if NexusState.spectateToggle then
                    NexusState.spectateToggle:Set(false)
                end
            end
        end)
        
        -- While spectating, watch the target's CharacterAdded
        local function monitorTarget()
            if spectateEnabled and spectateTarget then
                if charAddedConn then charAddedConn:Disconnect() end
                charAddedConn = spectateTarget.CharacterAdded:Connect(function()
                    task.wait(0.5)
                    onTargetCharacterAdded()
                end)
            else
                if charAddedConn then
                    charAddedConn:Disconnect()
                    charAddedConn = nil
                end
            end
        end
        
        -- Wrap startSpectate to attach the monitor
        local originalStart = startSpectate
        startSpectate = function()
            originalStart()
            monitorTarget()
        end
        
        -- Wrap stopSpectate to clean up
        local originalStop = stopSpectate
        stopSpectate = function()
            originalStop()
            if charAddedConn then
                charAddedConn:Disconnect()
                charAddedConn = nil
            end
        end
        
        table.insert(espConnections, { conn = playerRemovingConn })
    end
