                if not hrp then
                    hrp = targetModel:FindFirstChildWhichIsA("BasePart")
                end
                if not hrp then
                    NexusLib:Notify({ Title = "Learn Skill", Message = "Cannot find part to teleport to!", Duration = 2 })
                    return
                end
                
                local myChar = LocalPlayer.Character
                if not myChar then return end
                local myHrp = myChar:FindFirstChild("HumanoidRootPart")
                if not myHrp then return end
                
                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)
                
                NexusLib:Notify({ Title = "Learn Skill", Message = "Teleported to Sage Yijiu", Duration = 2 })
            end
        })
        -- ===== SECRET RODS SECTION =====
        -- Secret Rod list (models parented to a Folder under workspace.SecretRod)
        local function getSecretRodList()
            local rods = {}
            local secretRodFolder = workspace:FindFirstChild("SecretRod")
            if not secretRodFolder then return rods end
            
            for _, child in ipairs(secretRodFolder:GetDescendants()) do
                if typeof(child) == "Instance" and child:IsA("Model") and child.Parent and typeof(child.Parent) == "Instance" and child.Parent:IsA("Folder") then
                    table.insert(rods, child.Name)
                end
            end
            return rods
        end
        
        local rodList = getSecretRodList()
        if #rodList == 0 then
            table.insert(rodList, "No Secret Rods found")
        end
        
        local selectedRod = rodList[1]
        
        -- Dropdown
        local rodDropdown = NpcSection:CreateDropdown({
            Name = "Secret Rods",
            Options = rodList,
            Default = selectedRod,
            Callback = function(value)
                selectedRod = value
            end
        })
        
        -- Teleport button
        NpcSection:CreateButton({
            Name = "Teleport to selected Secret Rod",
            Callback = function()
                if not selectedRod or selectedRod == "No Secret Rods found" then
                    NexusLib:Notify({ Title = "Secret Rod", Message = "No Secret Rod selected!", Duration = 2 })
                    return
                end
                
                local secretRodFolder = workspace:FindFirstChild("SecretRod")
                if not secretRodFolder then
                    NexusLib:Notify({ Title = "Secret Rod", Message = "SecretRod folder not found!", Duration = 2 })
                    return
                end
                
                local targetModel = nil
                for _, child in ipairs(secretRodFolder:GetDescendants()) do
                    if typeof(child) == "Instance" and child:IsA("Model") and child.Name == selectedRod and child.Parent and typeof(child.Parent) == "Instance" and child.Parent:IsA("Folder") then
                        targetModel = child
                        break
                    end
                end
                
                if not targetModel then
                    NexusLib:Notify({ Title = "Secret Rod", Message = "Secret Rod not found!", Duration = 2 })
                    return
                end
                
                local hrp = targetModel:FindFirstChild("HumanoidRootPart") or targetModel.PrimaryPart
                if not hrp then
                    hrp = targetModel:FindFirstChildWhichIsA("BasePart")
                end
                if not hrp then
                    NexusLib:Notify({ Title = "Secret Rod", Message = "Cannot find part to teleport to!", Duration = 2 })
                    return
                end
                
                local myChar = LocalPlayer.Character
                if not myChar then return end
                local myHrp = myChar:FindFirstChild("HumanoidRootPart")
                if not myHrp then return end
                
                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)
                
                NexusLib:Notify({ Title = "Secret Rod", Message = "Teleported to " .. selectedRod, Duration = 2 })
            end
        })
    end
end

