        local HopSection = SettingsTab:CreateSection("Server Hop")
        NexusState.maxServerPlayers = NexusState.maxServerPlayers or 4
        NexusState.hopCooldownAt = NexusState.hopCooldownAt or 0

        local function fetchServers(cursor)
            local reqFn = (syn and syn.request) or http_request or request or (http and http.request) or (fluxus and fluxus.request)
            if type(reqFn) ~= "function" then return nil end
            local url = string.format("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100", game.PlaceId)
            if cursor and cursor ~= "" then url = url .. "&cursor=" .. cursor end
            local ok, res = pcall(reqFn, { Url = url, Method = "GET" })
            if not ok or not res then return nil end
            local body = res.Body or res.body
            if type(body) ~= "string" or body == "" then return nil end
            local ok2, data = pcall(function() return Services.HttpService:JSONDecode(body) end)
            if not ok2 or type(data) ~= "table" then return nil end
            return data
        end

        local function findLowServer(maxPlayers)
            local cursor = ""
            for _ = 1, 5 do
                local data = fetchServers(cursor)
                if not data or not data.data then return nil end
                for _, srv in ipairs(data.data) do
                    local playing = tonumber(srv.playing) or 999
                    local maxP = tonumber(srv.maxPlayers) or 0
                    if srv.id and srv.id ~= game.JobId and playing < maxP and playing <= maxPlayers then
                        return srv.id, playing, maxP
                    end
                end
                cursor = data.nextPageCursor
                if not cursor or cursor == "" then break end
            end
            return nil
        end


