                end
            })), "Toggle", "God ESP", {
                Name = "God ESP",
                Default = false,
                Callback = function(value)
                    if value then
                        startGodEsp()
                    else
                        stopGodEsp()
                    end
                end
            })
        end
        
        -- ===== NPCs ESP =====
        do
            local npcEspEnabled = false
            local npcEspThread = nil
            local npcEspHighlights = {}
            local npcFolder = workspace:FindFirstChild("NPC") and workspace.NPC:FindFirstChild("Function")
            
            local function createNpcEsp(npcModel)
                if not npcModel or typeof(npcModel) ~= "Instance" or not npcModel:IsA("Model") then return end
                if npcEspHighlights[npcModel] then return end
                
                if not npcModel.Parent or typeof(npcModel.Parent) ~= "Instance" or not npcModel.Parent:IsA("Folder") then return end
                
                local attachPart = npcModel:FindFirstChildWhichIsA("BasePart")
                if not attachPart then
                    attachPart = npcModel:FindFirstChildWhichIsA("BasePart", true)
                end
                if not attachPart then return end
                
                local highlight = Instance.new("Highlight")
                highlight.FillColor = Color3.fromRGB(255, 100, 0)
                highlight.FillTransparency = 0.4
                highlight.OutlineColor = Color3.fromRGB(255, 200, 50)
                highlight.OutlineTransparency = 0.2
                highlight.Adornee = npcModel
                highlight.Parent = npcModel
                
                local billboard = Instance.new("BillboardGui")
                billboard.Name = "NpcEspBillboard"
                billboard.Size = UDim2.new(0, 200, 0, 30)
                billboard.StudsOffset = Vector3.new(0, 2.5, 0)
                billboard.AlwaysOnTop = true
                billboard.Parent = attachPart
                
                local frame = Instance.new("Frame")
                frame.Size = UDim2.new(1, 0, 1, 0)
                frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
                frame.BackgroundTransparency = 0.5
                frame.BorderSizePixel = 0
                frame.Parent = billboard
                
                local corner = Instance.new("UICorner")
                corner.CornerRadius = UDim.new(0, 4)
                corner.Parent = frame
                
                local label = Instance.new("TextLabel")
                label.Size = UDim2.new(1, 0, 1, 0)
                label.BackgroundTransparency = 1
                label.Font = Enum.Font.GothamBold
                label.TextSize = 14
                label.TextColor3 = Color3.fromRGB(255, 150, 50)
                label.Text = "NPC | " .. npcModel.Name
                label.TextScaled = false
                label.TextXAlignment = Enum.TextXAlignment.Center
                label.TextYAlignment = Enum.TextYAlignment.Center
                label.Parent = frame
                
                npcEspHighlights[npcModel] = {
                    highlight = highlight,
                    billboard = billboard,
                    attachPart = attachPart,
                }
            end
            
            local function removeNpcEsp(npcModel)
                local data = npcEspHighlights[npcModel]
                if data then
                    if data.highlight then data.highlight:Destroy() end
                    if data.billboard then data.billboard:Destroy() end
                    npcEspHighlights[npcModel] = nil
                end
            end
            
            local function clearAllNpcEsp()
                for model, data in pairs(npcEspHighlights) do
                    pcall(function()
                        if data.highlight then data.highlight:Destroy() end
                        if data.billboard then data.billboard:Destroy() end
                    end)
                end
                npcEspHighlights = {}
            end
            
            local function scanAllNpcs()
                if not npcFolder then return end
                for _, child in ipairs(npcFolder:GetDescendants()) do
                    if typeof(child) == "Instance" and child:IsA("Model") and child.Parent and typeof(child.Parent) == "Instance" and child.Parent:IsA("Folder") then
                        if not npcEspHighlights[child] then
                            pcall(function() createNpcEsp(child) end)
                        end
                    end
                end
            end
            
            local function startNpcEsp()
                if npcEspEnabled then return end
                npcEspEnabled = true
                scanAllNpcs()
                
                if npcFolder then
                    local npcAddedConn = npcFolder.DescendantAdded:Connect(function(desc)
                        if npcEspEnabled and typeof(desc) == "Instance" and desc:IsA("Model") and desc.Parent and typeof(desc.Parent) == "Instance" and desc.Parent:IsA("Folder") then
                            task.wait(0.1)
                            pcall(function()
         ]=],[=[
                       if not npcEspHighlights[desc] then
                                    createNpcEsp(desc)
                                end
                            end)
                        end
                    end)
                    table.insert(espConnections, { conn = npcAddedConn })
                end
                
                npcEspThread = task.spawn(function()
                    while npcEspEnabled do
                        task.wait(10)
                        if npcEspEnabled then
                            pcall(function()
                                for model, data in pairs(npcEspHighlights) do
                                    if not model.Parent then
                                        removeNpcEsp(model)
                                    end
                                end
                                scanAllNpcs()
                            end)
                        end
                    end
                end)
                
                NexusLib:Notify({ Title = "NPCs ESP", Message = "NPCs ESP enabled!", Duration = 2 })
            end
            
            local function stopNpcEsp()
                npcEspEnabled = false
                if npcEspThread then
                    task.cancel(npcEspThread)
                    npcEspThread = nil
                end
                clearAllNpcEsp()
                NexusLib:Notify({ Title = "NPCs ESP", Message = "NPCs ESP disabled!", Duration = 2 })
            end
            
            Cfg.register(EspSection:CreateToggle(Cfg.wrap("Toggle", "NPCs ESP", {
                Name = "NPCs ESP",
                Default = false,
                Callback = function(value)
                    if value then
                        startNpcEsp()
                    else
                        stopNpcEsp()
                    end
                end
            })), "Toggle", "NPCs ESP", {
                Name = "NPCs ESP",
                Default = false,
                Callback = function(value)
                    if value then
                        startNpcEsp()
                    else
                        stopNpcEsp()
                    end
                end
            })
        end
    end
end

