local CONFIG = {
    API_URL = "https://vgvaxescpirfdkrcamyk.supabase.co/functions/v1/key-system",
    GET_KEY_URL = "https://vgvaxescpirfdkrcamyk.supabase.co/functions/v1/key-system",
    KEY_FILES = { "NexusPremiumKey.txt", "NexusFreemiumKey.txt" },
}

local function notify(message)
    pcall(print, "[Nexus Guard] " .. tostring(message))
end

local function copyText(value)
    local fn = setclipboard or toclipboard or writeclipboard or (syn and syn.write_clipboard)
    if type(fn) == "function" then return pcall(fn, tostring(value)) end
    return false
end

local function requestAdapter()
    return (syn and syn.request) or http_request or request or (http and http.request)
end

local function getHwid()
    local value
    pcall(function() if type(gethwid) == "function" then value = gethwid() end end)
    if type(value) ~= "string" or #value < 4 then
        pcall(function() value = game:GetService("RbxAnalyticsService"):GetClientId() end)
    end
    return tostring(value or ("player:" .. tostring(LocalPlayer.UserId))) .. ":" .. tostring(LocalPlayer.UserId)
end

local function readKey()
    if type(runtime.Key) == "string" and #runtime.Key >= 4 then return runtime.Key end
    for _, name in ipairs(CONFIG.KEY_FILES) do
        local ok, value = pcall(function()
            if isfile and readfile and isfile(name) then return readfile(name) end
        end)
        if ok and type(value) == "string" and #value >= 4 then return value end
    end
end

local function saveKey(key, tier)
    if not (writefile and type(key) == "string") then return end
    local name = tier == "PREMIUM" and CONFIG.KEY_FILES[1] or CONFIG.KEY_FILES[2]
    pcall(writefile, name, key)
end

local function validate(key)
    local body = HttpService:JSONEncode({
        action = "validate", key = key, hwid = getHwid(),
        bundle = "hub", protocol_version = 3,
    })
    local fn = requestAdapter()
    local ok, result = pcall(function()
        if fn then
            local response = fn({
                Url = CONFIG.API_URL, Method = "POST",
                Headers = { ["Content-Type"] = "application/json" },
                Body = body, Timeout = 20,
            })
            return HttpService:JSONDecode(response.Body or response.body or "{}")
        end
        return HttpService:JSONDecode(HttpService:PostAsync(
            CONFIG.API_URL, body, Enum.HttpContentType.ApplicationJson, false))
    end)
    if ok and type(result) == "table" then return result end
end

local function clearKeys()
    if not (delfile and isfile) then return end
    for _, name in ipairs(CONFIG.KEY_FILES) do
        pcall(function() if isfile(name) then delfile(name) end end)
    end
end

local function createUi(defaultKey)
    local parent
    pcall(function() parent = gethui and gethui() end)
    if not parent then parent = LocalPlayer:FindFirstChildOfClass("PlayerGui") end
    if not parent then parent = game:GetService("CoreGui") end
    if not parent then notify("Cannot create key UI."); return end

    local gui = Instance.new("ScreenGui")
    gui.Name = "NexusXhiderKeySystem"
    gui.ResetOnSpawn = false
    gui.Parent = parent
    local frame = Instance.new("Frame")
    frame.Size = UDim2.fromOffset(390, 255)
    frame.Position = UDim2.new(0.5, -195, 0.5, -127)
    frame.BackgroundColor3 = Color3.fromRGB(20, 22, 30)
    frame.Parent = gui
    Instance.new("UICorner", frame).CornerRadius = UDim.new(0, 10)

    local title = Instance.new("TextLabel")
    title.Size = UDim2.new(1, 0, 0, 42)
    title.BackgroundTransparency = 1
    title.Text = "NEXUS KEY SYSTEM"
    title.TextColor3 = Color3.new(1, 1, 1)
    title.Font = Enum.Font.GothamBold
    title.TextSize = 18
    title.Parent = frame

    local box = Instance.new("TextBox")
    box.Size = UDim2.new(1, -32, 0, 42)
    box.Position = UDim2.fromOffset(16, 56)
    box.Text = tostring(defaultKey or "")
    box.PlaceholderText = "Paste key here..."
    box.ClearTextOnFocus = false
    box.TextColor3 = Color3.new(1, 1, 1)
    box.BackgroundColor3 = Color3.fromRGB(35, 38, 50)
    box.Parent = frame

    local status = Instance.new("TextLabel")
    status.Size = UDim2.new(1, -32, 0, 35)
    status.Position = UDim2.fromOffset(16, 105)
    status.BackgroundTransparency = 1
    status.Text = "Enter a key and press Submit."
    status.TextColor3 = Color3.fromRGB(180, 185, 200)
    status.Parent = frame

    local submit = Instance.new("TextButton")
    submit.Size = UDim2.new(0.47, -8, 0, 42)
    submit.Position = UDim2.fromOffset(16, 155)
    submit.Text = "Submit Key"
    submit.TextColor3 = Color3.new(1, 1, 1)
    submit.BackgroundColor3 = Color3.fromRGB(60, 110, 220)
    submit.Parent = frame

    local getKey = Instance.new("TextButton")
    getKey.Size = UDim2.new(0.47, -8, 0, 42)
    getKey.Position = UDim2.new(0.53, 0, 0, 155)
    getKey.Text = "Get Key"
    getKey.TextColor3 = Color3.new(1, 1, 1)
    getKey.BackgroundColor3 = Color3.fromRGB(45, 50, 65)
    getKey.Parent = frame

    local function finish(result, value)
        if not result or result.ok ~= true then
            local code = result and tostring(result.code or "") or "NETWORK_ERROR"
            if code == "KEY_EXPIRED" or code == "KEY_DISABLED" or code == "INVALID_KEY" or code == "HWID_MISMATCH" then
                clearKeys()
                pcall(function() LocalPlayer:Kick("Nexus: key expired or revoked.") end)
            end
            status.Text = "Failed: " .. code
            return
        end
        local tier = string.upper(tostring(result.tier or ""))
        if tier ~= "PREMIUM" and tier ~= "FREEMIUM" then status.Text = "Unknown key tier."; return end
        runtime.Key = value
        runtime.NexusVerifiedTier = tier
        runtime.NexusGuardNonce = result.server_nonce or result.launch_token or result.device_token
        runtime.NexusPremiumVerified = tier == "PREMIUM" and true or nil
        runtime.NexusFreemiumVerified = tier == "FREEMIUM" and true or nil
        saveKey(value, tier)
        local libChunk, libError = loadstring(EmbeddedLibrary, "@NexusLib.lua")
        if not libChunk then status.Text = "Library compile error: " .. tostring(libError); return end
        local libOk, lib = pcall(libChunk)
        if not libOk or type(lib) ~= "table" then status.Text = "Library failed: " .. tostring(lib); return end
        runtime.NexusLib = lib
        local source = tier == "PREMIUM" and EmbeddedPremium or EmbeddedFreemium
        local main, compileError = loadstring(source, "@nexus_embedded_" .. tier .. ".lua")
        if not main then status.Text = "Compile error: " .. tostring(compileError); return end
        gui:Destroy()
        local ok, err = pcall(main)
        if not ok then notify("Script error: " .. tostring(err)) end
    end

    getKey.MouseButton1Click:Connect(function()
        if copyText(CONFIG.GET_KEY_URL) then status.Text = "Get-key link copied." end
    end)
    submit.MouseButton1Click:Connect(function()
        local value = tostring(box.Text or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if #value < 4 then status.Text = "Please enter a valid key."; return end
        status.Text = "Checking key..."
        task.spawn(function() finish(validate(value), value) end)
    end)
end

local saved = readKey()
createUi(saved)
